    /// Structural selected-proof grammar before runtime/storage activation.
    /// Shared validation subsequently proves every witness and affected row.
    private static func completeSaveEnvelope(_ value: Any?, version: Int = 2) throws -> [String: Any] {
        guard let envelope = value as? [String: Any], Set(envelope.keys) == Set(["request", "prepared"]),
              let request = envelope["request"] as? [String: Any],
              Set(request.keys) == Set(["version", "kind", "checkpoint", "ownedDraft", "saveRequest"]),
              isInteger(request["version"], equalTo: version), request["kind"] as? String == "owned-editor-file-edit-save",
              let prepared = envelope["prepared"] as? [String: Any], Set(prepared.keys) == Set(["version", "kind", "request", "decision"]),
              isInteger(prepared["version"], equalTo: version), prepared["kind"] as? String == "owned-editor-file-edit-save",
              equalJSON(prepared["request"], request), let decision = prepared["decision"] as? [String: Any],
              Set(decision.keys) == Set(["kind", "prepared"]), let proof = decision["prepared"] as? [String: Any],
              isInteger(proof["version"], equalTo: 2), equalJSON(proof["request"], request["saveRequest"]),
              proof["witness"] is [String: Any], proof["result"] is [String: Any] else { throw ownedSaveFailure }
        _ = try completeSaveRequest(request["saveRequest"])
        switch decision["kind"] as? String {
        case "changed":
            guard Set(proof.keys) == Set(["version", "kind", "request", "witness", "effect", "result", "rawBefore"]),
                  proof["kind"] as? String == "save", let effect = proof["effect"] as? [String: Any],
                  effect["tasks"] is [[String: Any]], effect["projects"] is [[String: Any]], effect["sections"] is [[String: Any]],
                  proof["rawBefore"] is [String: Any] else { throw ownedSaveFailure }
        case "noop":
            guard Set(proof.keys) == Set(["version", "kind", "request", "witness", "rawBefore", "result"]),
                  proof["kind"] as? String == "noop", proof["rawBefore"] is [String: Any] else { throw ownedSaveFailure }
        default: throw ownedSaveFailure
        }
        return envelope
    }
    private static func mixedSaveSelection(_ version: Any?) -> NativeAttachmentDraftCoordinator.MixedSaveSelection? {
        if isInteger(version, equalTo: 2) { return .legacy }
        if isInteger(version, equalTo: 3) { return .complete }
        if isInteger(version, equalTo: 4) { return .completeHash }
        if isInteger(version, equalTo: 5) { return .completeAvailability }
        return nil
    }
    /// Does not read files or assert a Save outcome. Startup separately binds
    /// the native files, then pure shared validation proves the complete effect.
    private func ownedSaveJournal(_ command: PendingCommand, checkingNative: Bool = true) throws -> OwnedSaveJournal {
        guard command.version == 2, command.method == Self.ownedSaveMethod,
              try JSONEncoder().encode(command).count <= Self.ownedSaveMaximumBytes,
              let attempt = command.editorDraft,
              let args = try NativeJSON.jsonObject(with: Data(command.argumentsJSON.utf8)) as? [String], args.count == 1,
              let wrapper = try NativeJSON.jsonObject(with: Data(args[0].utf8)) as? [String: Any],
              Set(wrapper.keys) == Set(["version", "recordSHA256", "envelope"]), Self.isInteger(wrapper["version"], equalTo: 1),
              let fingerprint = wrapper["recordSHA256"] as? String, fingerprint.utf8.count == 64,
              fingerprint.utf8.allSatisfy({ (48...57).contains($0) || (97...102).contains($0) }),
              let envelope = wrapper["envelope"] as? [String: Any], Set(envelope.keys) == Set(["request", "prepared"]),
              let request = envelope["request"] as? [String: Any],
              Set(request.keys) == Set(["version", "kind", "checkpoint", "ownedDraft", "saveRequest"]),
              Self.isInteger(request["version"], equalTo: 1), request["kind"] as? String == "owned-editor-file-add-save",
              let checkpoint = request["checkpoint"] as? [String: Any],
              Set(checkpoint.keys) == Set(["version", "sessionID", "taskID", "generation", "payloadJSON"]),
              Self.isInteger(checkpoint["version"], equalTo: 1), Self.isInteger(checkpoint["generation"]),
              let snapshot = try? JSONDecoder().decode(EditorDraftSnapshot.self, from: Data(Self.ownedJSON(checkpoint).utf8)),
              let owned = request["ownedDraft"] as? [String: Any],
              Set(owned.keys) == Set(["version", "taskID", "initialPayloadJSON", "beforePayloadJSON", "priorAdditions", "managedDirectoryURI"]),
              Self.isInteger(owned["version"], equalTo: 2), let task = owned["taskID"] as? String,
              Self.ownedEqual(task, snapshot.taskID), let latest = owned["beforePayloadJSON"] as? String,
              Self.ownedEqual(latest, snapshot.payloadJSON), owned["initialPayloadJSON"] is String,
              let additions = owned["priorAdditions"] as? [[String: Any]], (1...128).contains(additions.count),
              owned["managedDirectoryURI"] is String,
              let save = request["saveRequest"] as? [String: Any],
              let prepared = envelope["prepared"] as? [String: Any],
              Set(prepared.keys) == Set(["version", "kind", "request", "preparedAt", "deviceIdBefore", "deviceIdToInitialize", "scope", "effect"]),
              Self.isInteger(prepared["version"], equalTo: 1), prepared["kind"] as? String == "owned-editor-file-add-save",
              Self.equalJSON(prepared["request"], request), prepared["preparedAt"] is String,
              prepared["scope"] is [String: Any], prepared["effect"] is [String: Any] else { throw Self.ownedSaveFailure }
        try editorDrafts.preflightOwnedSave(expected: snapshot, attempt: attempt)
        guard Self.equalJSON(try Self.ownedOriginalRequest(attempt), save) else { throw Self.ownedSaveFailure }
        if case .rejected(let message) = command.terminal {
            guard isDefiniteRejection(message, method: command.method) else { throw Self.ownedSaveFailure }
        }
        var actual: NativeAttachmentDraftStore.Record?
        if checkingNative {
            let success: Bool
            if case .success = command.terminal { success = true } else { success = false }
            actual = try NativeAttachmentDraftStore(databaseURL: databaseURL).read()
            if let actual {
                guard Self.ownedEqual(try NativeAttachmentDraftStore.ownedSaveFingerprint(actual), fingerprint),
                      Self.ownedEqual(actual.session.checkpoint, snapshot),
                      Self.equalJSON(try NativeJSON.jsonObject(with: Data(NativeAttachmentDraftCoordinator.ownedSaveLineageJSON(actual).utf8)), owned) else {
                    throw Self.ownedSaveFailure
                }
            } else if !success { throw Self.ownedSaveFailure }
            if let current = try editorDrafts.read() {
                guard Self.ownedEqual(current.snapshot, snapshot) else { throw Self.ownedSaveFailure }
                if let frozen = current.attempt {
                    guard Self.ownedEqual(frozen, attempt) else { throw Self.ownedSaveFailure }
                } else if case .rejected = command.terminal {
                    // A prior exact thaw may precede a failed journal clear.
                } else { throw Self.ownedSaveFailure }
            } else if !success { throw Self.ownedSaveFailure }
        }
        return .init(fingerprint: fingerprint, envelopeJSON: try Self.ownedJSON(envelope),
                     snapshot: snapshot, attempt: attempt, record: actual)
    }

    private func decodeOwnedSaveJournal(_ data: Data, checkingNative: Bool) throws -> PendingCommand {
        guard data.count <= Self.ownedSaveMaximumBytes,
              let raw = try NativeJSON.jsonObject(with: data) as? [String: Any],
              Set(raw.keys) == Set(["version", "method", "argumentsJSON", "editorDraft"]
                + (raw["terminal"] == nil ? [] : ["terminal"])),
              let draft = raw["editorDraft"] as? [String: Any],
              Set(draft.keys) == Set(["id", "sessionID", "taskID", "generation", "method", "argumentsJSON"]),
              let command = try? JSONDecoder().decode(PendingCommand.self, from: data), command.method == Self.ownedSaveMethod else {
            throw Self.ownedSaveFailure
        }
        if let terminal = raw["terminal"] {
            guard let object = terminal as? [String: Any], object.count == 1,
                  let kind = object.keys.first, ["success", "rejected"].contains(kind),
                  let body = object[kind] as? [String: Any], Set(body.keys) == Set(["_0"]), body["_0"] is String else {
                throw Self.ownedSaveFailure
            }
        }
        _ = try ownedSaveJournal(command, checkingNative: checkingNative)
        return command
    }

    /// Only used by the new owned command's mutation guards. The legacy
    /// journal loader and its historical transport limits remain unchanged.
    private func ownedJournalBytes() throws -> Data? {
        try readJournalBytes(maximumBytes: Self.ownedSaveMaximumBytes, failure: Self.ownedSaveFailure, singleLink: true)
    }
    private func readJournalBytes(maximumBytes: Int?, failure: HostFailure, singleLink: Bool, url: URL? = nil) throws -> Data? {
        try Self.readBoundJournalBytes(url ?? journalURL, maximumBytes: maximumBytes, failure: failure, singleLink: singleLink)
    }
    private static func readBoundJournalBytes(_ target: URL, maximumBytes: Int?, failure: HostFailure, singleLink: Bool) throws -> Data? {
        let fd = open(target.path, O_RDONLY | O_NOFOLLOW | O_NONBLOCK | O_CLOEXEC)
        if fd < 0 {
            if errno == ENOENT { return nil }
            throw failure
        }
        defer { Darwin.close(fd) }
        var before = stat()
        guard fstat(fd, &before) == 0, (before.st_mode & S_IFMT) == S_IFREG, !singleLink || before.st_nlink == 1,
              before.st_size >= 0, maximumBytes.map({ before.st_size <= Int64($0) }) ?? true else { throw failure }
        var result = Data(), buffer = Data(count: 64 * 1024)
        while true {
            let count = buffer.withUnsafeMutableBytes { Darwin.read(fd, $0.baseAddress, $0.count) }
            if count < 0 && errno == EINTR { continue }
            guard count >= 0 else { throw failure }
            if count == 0 { break }
            guard maximumBytes.map({ result.count + count <= $0 }) ?? true else { throw failure }
            result.append(buffer.prefix(count))
        }
        var after = stat(), named = stat()
        func same(_ lhs: stat, _ rhs: stat) -> Bool {
            lhs.st_dev == rhs.st_dev && lhs.st_ino == rhs.st_ino && lhs.st_mode == rhs.st_mode
                && lhs.st_nlink == rhs.st_nlink && lhs.st_size == rhs.st_size
                && lhs.st_mtimespec.tv_sec == rhs.st_mtimespec.tv_sec && lhs.st_mtimespec.tv_nsec == rhs.st_mtimespec.tv_nsec
                && lhs.st_ctimespec.tv_sec == rhs.st_ctimespec.tv_sec && lhs.st_ctimespec.tv_nsec == rhs.st_ctimespec.tv_nsec
        }
        guard result.count == Int(before.st_size), fstat(fd, &after) == 0, lstat(target.path, &named) == 0,
              same(before, after), same(after, named) else { throw failure }
        return result
    }
    private func ownedEncoded<T: Encodable>(_ value: T) throws -> Data {
        let encoder = JSONEncoder(); encoder.outputFormatting = [.sortedKeys]; return try encoder.encode(value)
    }
    private func decodeOwnedJournal(_ data: Data, method: String) throws -> PendingCommand {
        if method == Self.mixedSaveMethod { return try decodeMixedSaveJournal(data, checkingNative: false) }
        if method == Self.ownedDiscardMethod { return try decodeOwnedDiscardJournal(data, checkingNative: false) }
        return try decodeOwnedSaveJournal(data, checkingNative: false)
    }
    private func requireOwnedJournalOnDisk(_ command: PendingCommand) throws {
        guard let data = try ownedJournalBytes() else { throw Self.ownedSaveFailure }
        let actual = try decodeOwnedJournal(data, method: command.method)
        guard try ownedEncoded(actual) == ownedEncoded(command) else { throw Self.ownedSaveFailure }
    }
    private func requireOwnedJournalWriteIdentity(_ command: PendingCommand) throws {
        guard let bytes = try ownedJournalBytes() else { return }
        let actual = try decodeOwnedJournal(bytes, method: command.method)
        var before = actual, after = command; before.terminal = nil; after.terminal = nil
        guard try ownedEncoded(before) == ownedEncoded(after) else { throw Self.ownedSaveFailure }
        if let terminal = actual.terminal {
            if command.method == Self.mixedSaveMethod {
                try requireMixedSaveTransition(actual, command)
                return
            }
            guard let incoming = command.terminal, try ownedEncoded(terminal) == ownedEncoded(incoming) else { throw Self.ownedSaveFailure }
        }
        if actual.terminal == nil, command.method == Self.mixedSaveMethod, case .success = command.terminal {
            guard let state = try mixedSaveJournal(command, checkingNative: false).settlement,
                  state.phase == "domainSaved", state.targets.allSatisfy({ $0 == nil }), state.stages.allSatisfy({ $0 == nil }) else {
                throw Self.ownedSaveFailure
            }
        }
    }

    private func mixedSaveStateJSON(_ state: MixedSaveSettlement, stages: [String]) throws -> String {
        try Self.ownedJSON(["version": 1, "kind": "owned-editor-file-edit-settlement", "phase": state.phase,
            "resultJSON": state.resultJSON,
            "targets": state.targets.enumerated().map { ["index": $0.offset, "outcome": $0.element.map { $0 as Any } ?? NSNull()] },
            "stages": zip(stages, state.stages).map { ["requestId": $0.0, "outcome": $0.1.map { $0 as Any } ?? NSNull()] }] as [String: Any])
    }
    private func mixedSaveState(_ raw: String, authorities: [NativeAttachmentDraftCoordinator.MixedSaveAuthority],
                                stages: [String], selection: NativeAttachmentDraftCoordinator.MixedSaveSelection = .legacy) throws -> MixedSaveSettlement {
        guard raw.utf8.count <= Self.ownedSaveMaximumBytes,
              let value = try NativeJSON.jsonObject(with: Data(raw.utf8)) as? [String: Any],
              Set(value.keys) == Set(["version", "kind", "phase", "resultJSON", "targets", "stages"]),
              Self.isInteger(value["version"], equalTo: 1), value["kind"] as? String == "owned-editor-file-edit-settlement",
              let phase = value["phase"] as? String, ["domainSaved", "settled"].contains(phase),
              let result = value["resultJSON"] as? String, let resultValue = try NativeJSON.jsonObject(with: Data(result.utf8)) as? [String: Any],
              Set(resultValue.keys) == Set(["id", "draft"] + (selection.isComplete && resultValue["cancellation"] != nil ? ["cancellation"] : [])),
              resultValue["id"] is String, resultValue["draft"] is [String: Any],
              let targets = value["targets"] as? [[String: Any]], targets.count == authorities.count,
              let privateStages = value["stages"] as? [[String: Any]], privateStages.count == stages.count else { throw Self.ownedSaveFailure }
        var outcomes: [String?] = [], stageOutcomes: [String?] = [], unresolved = false
        for (index, target) in targets.enumerated() {
            guard Set(target.keys) == Set(["index", "outcome"]), Self.isInteger(target["index"], equalTo: index) else { throw Self.ownedSaveFailure }
            if target["outcome"] is NSNull { unresolved = true; outcomes.append(nil); continue }
            guard !unresolved, let outcome = target["outcome"] as? String else { throw Self.ownedSaveFailure }
            let permitted: Set<String>
            switch authorities[index] {
            case .ownedAdd: permitted = ["removed", "absent", "referenced"]
            case .ownedAvailability: permitted = ["removed", "absent", "referenced", "taskChanged"]
            case .borrowedAvailability: permitted = ["notOwned", "referenced", "taskChanged"]
            case .baseline(let observation):
                permitted = Set<String>(["referenced", "taskChanged"]).union(observation.kind == "present"
                    ? ["removed", "absent", "generationChanged", "unsafeEntry"] : [observation.kind])
            }
            guard permitted.contains(outcome) else { throw Self.ownedSaveFailure }
            outcomes.append(outcome)
        }
        for (index, stage) in privateStages.enumerated() {
            guard Set(stage.keys) == Set(["requestId", "outcome"]), let id = stage["requestId"] as? String,
                  Self.ownedEqual(id, stages[index]) else { throw Self.ownedSaveFailure }
            if stage["outcome"] is NSNull { unresolved = true; stageOutcomes.append(nil); continue }
            guard !unresolved, let outcome = stage["outcome"] as? String, ["removed", "missing"].contains(outcome) else { throw Self.ownedSaveFailure }
            stageOutcomes.append(outcome)
        }
        guard phase != "settled" || !unresolved else { throw Self.ownedSaveFailure }
        return .init(phase: phase, resultJSON: result, targets: outcomes, stages: stageOutcomes)
    }
    private func mixedSaveManagedURI() throws -> String {
        guard let jobs = attachmentJobs,
              let directories = try NativeJSON.jsonObject(with: Data(jobs.directoriesJSON.utf8)) as? [String: Any],
              let document = directories["document"] as? String, let root = URL(string: document) else { throw Self.ownedSaveFailure }
        return root.appendingPathComponent("attachments", isDirectory: true).absoluteString
    }
    /// Only the canonical native spelling and Apple's actual fixed system alias
    /// can participate in a bounded terminal mapping. No arbitrary URL rebasing.
    private static func mixedSaveCanonicalPath(_ uri: String, directory: Bool) throws -> String {
        guard !uri.isEmpty, uri.utf8.count <= 16 * 1024 else { throw ownedSaveFailure }
        let path = try NativeAttachmentFiles.filePath(uri)
        guard !path.utf8.contains(92) else { throw ownedSaveFailure }
        let trimmed = directory && path.hasSuffix("/") ? String(path.dropLast()) : path
        let components = trimmed.split(separator: "/", omittingEmptySubsequences: false)
        guard components.count > 1, components.first == "", components.dropFirst().allSatisfy({ !$0.isEmpty }) else {
            throw ownedSaveFailure
        }
        let canonical = URL(fileURLWithPath: trimmed, isDirectory: directory).absoluteString
