    private func requireMixedSaveAuthority(_ command: PendingCommand, turn: MixedSaveTurn,
                                           cancellation: NativeAttachmentCancellation, promotion: Bool = false,
                                           editorAbsent: Bool = false, sidecarAbsent: Bool = false,
