              try mixedSaveFileBinding(editorDrafts.url, maximumBytes: 3_000_000) == turn.editor else { throw Self.ownedSaveFailure }
    }
    func saveAttachmentDraftMixed(saveRequestJSON: String, expectedSession: String, expectedGeneration: Int,
                                  cancellation: NativeAttachmentCancellation) throws -> String {
        try saveAttachmentDraftMixed(saveRequestJSON: saveRequestJSON, expectedSession: expectedSession,
            expectedGeneration: expectedGeneration, selection: .legacy, cancellation: cancellation)
    }
    private func completeSaveSelection() throws -> NativeAttachmentDraftCoordinator.MixedSaveSelection {
        guard let binding = try NativeAttachmentDraftStore(databaseURL: databaseURL).readVersioned() else { throw Self.ownedSaveFailure }
        switch binding.record {
        case .mixed(let record): return record.version == 4 ? .completeHash : .complete
        case .availability: return .completeAvailability
        case .legacy: throw Self.ownedSaveFailure
        }
    }
    func saveAttachmentDraftComplete(saveRequestJSON: String, expectedSession: String, expectedGeneration: Int,
                                     cancellation: NativeAttachmentCancellation) throws -> String {
        try saveAttachmentDraftMixed(saveRequestJSON: saveRequestJSON, expectedSession: expectedSession,
            expectedGeneration: expectedGeneration, selection: try completeSaveSelection(), cancellation: cancellation)
    }
    private func saveAttachmentDraftMixed(saveRequestJSON: String, expectedSession: String, expectedGeneration: Int,
                                         selection: NativeAttachmentDraftCoordinator.MixedSaveSelection,
                                         cancellation: NativeAttachmentCancellation) throws -> String {
        guard providerCopy?.receipt != nil || providerCopy == nil else { throw HostFailure("Attachment provider is loading") }
        do {
            let coordinator = try attachmentDraftCoordinatorV3(cancellation: cancellation)
            let prepared: NativeAttachmentDraftCoordinator.MixedSavePreparation
            if selection == .completeAvailability {
                let value = try coordinator.prepareAvailabilitySave(saveRequestJSON, session: expectedSession, generation: expectedGeneration, cancellation: cancellation)
                let binding = NativeAttachmentDraftStore.VersionedSnapshot(record: .availability(value.binding.record), bytes: value.binding.bytes,
                    device: value.binding.device, inode: value.binding.inode)
                prepared = .init(binding: binding, snapshot: value.snapshot, fingerprint: value.fingerprint, envelopeJSON: value.envelopeJSON,
                    resultJSON: value.resultJSON, candidates: value.candidates, stages: value.stages)
            } else {
                prepared = try coordinator.prepareMixedSave(saveRequestJSON, session: expectedSession, generation: expectedGeneration,
                    selection: selection, cancellation: cancellation)
            }
            let attempt = EditorDraftAttempt(id: UUID().uuidString.lowercased(), sessionID: prepared.snapshot.sessionID,
                taskID: prepared.snapshot.taskID, generation: prepared.snapshot.generation, method: "attachmentDraftSave",
                argumentsJSON: try Self.ownedJSON([saveRequestJSON]))
            let wrapper = try Self.ownedJSON(["version": selection.wrapperVersion, "recordSHA256": prepared.fingerprint,
                "envelope": try NativeJSON.jsonObject(with: Data(prepared.envelopeJSON.utf8)),
                "candidates": try prepared.candidates.map { ["index": $0.index, "authority": try $0.authority.object()] as [String: Any] },
                "stages": prepared.stages] as [String: Any])
            let command = PendingCommand(version: 2, method: Self.mixedSaveMethod, argumentsJSON: try Self.ownedJSON([wrapper]), editorDraft: attempt)
            try preflightMixedSave(command, snapshot: prepared.snapshot, result: prepared.resultJSON, candidates: prepared.candidates)
            guard let runtime = context, let jobs = attachmentJobs else { throw Self.ownedSaveFailure }
            let turn = MixedSaveTurn(generation: attachmentGeneration, runtime: runtime, jobs: jobs, record: prepared.binding,
                editor: try mixedSaveFileBinding(editorDrafts.url, maximumBytes: 3_000_000))
            turn.validated = try mixedSaveJournal(command, checkingNative: false)
            try requireUnjournaledMixedSave(prepared, turn: turn, attempt: nil, cancellation: cancellation)
            try editorDrafts.freezeOwnedSaveMatching(expected: prepared.snapshot, attempt: attempt)
            turn.editor = try mixedSaveFileBinding(editorDrafts.url, maximumBytes: 3_000_000)
            #if DEBUG
            try attachmentDraftHooks?.boundary?(.afterSaveFreeze)
            #endif
            try requireUnjournaledMixedSave(prepared, turn: turn, attempt: attempt, cancellation: cancellation)
            pending = command
            try persist(command, mixedGuard: { [unowned self] in
                _ = try self.requireMixedSaveEvidence(command, turn: turn, cancellation: cancellation, state: nil)
            })
            guard let written = try mixedSaveFileBinding(journalURL, maximumBytes: Self.ownedSaveMaximumBytes),
                  written.bytes == (try ownedEncoded(command)) else { throw Self.ownedSaveFailure }
            turn.journal = written
            turn.acknowledged = command
            #if DEBUG
            try attachmentDraftHooks?.boundary?(.afterSaveJournal)
            #endif
            return try executeMixedSave(command, cancellation: cancellation, turn: turn, firstInvocation: true).value()
        } catch let known as CoreHostAttachmentCleanupPending { throw known }
        catch let rejected as CoreHostRejection { throw rejected }
        catch { throw Self.ownedSaveFailure }
    }
    private func persistMixedSaveProgress(_ command: PendingCommand, turn: MixedSaveTurn,
                                          cancellation: NativeAttachmentCancellation,
                                          before: AttachmentDraftBoundary, after: AttachmentDraftBoundary) throws {
        guard let captured = turn.validated else { throw Self.ownedSaveFailure }
        let state: MixedSaveSettlement?
        if case .success(let raw) = command.terminal {
            state = try mixedSaveState(raw, authorities: captured.authorities, stages: captured.stages, selection: captured.selection)
        }
        else { state = nil }
        pending = command
        _ = try requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation, promotion: true, proposedState: state)
        #if DEBUG
        try attachmentDraftHooks?.boundary?(before)
        #endif
        _ = try requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation, promotion: true, proposedState: state)
        let data = try JSONEncoder().encode(command)
        guard data.count <= Self.ownedSaveMaximumBytes else { throw Self.ownedSaveFailure }
        #if DEBUG
        try faults?.journalWrite?()
        #endif
        _ = try requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation, promotion: true, proposedState: state)
        try DurableFile.write(data, to: journalURL, privateDraft: true)
        guard let written = try mixedSaveFileBinding(journalURL, maximumBytes: Self.ownedSaveMaximumBytes), written.bytes == data else { throw Self.ownedSaveFailure }
        // Only a confirmed write advances the acknowledged progress and inode.
        turn.journal = written; turn.acknowledged = command; turn.acknowledgedState = state
        #if DEBUG
        try attachmentDraftHooks?.boundary?(after)
        #endif
        _ = try requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation)
    }
    /// Exactly one native-held branch completes synchronously. No JSC work,
    /// pump or logging occurs between shared policy selection and typed IO.
    private func mixedSaveTargetHandoff(_ command: PendingCommand, turn: MixedSaveTurn,
                                        candidate: NativeAttachmentDraftCoordinator.MixedSaveCandidate,
                                        cancellation: NativeAttachmentCancellation) throws -> String {
        let captured = try requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation, editorAbsent: true)
        guard let binding = captured.binding,
              let host = turn.runtime.objectForKeyedSubscript("MindwtrHost"), !invoking else { throw Self.ownedSaveFailure }
        let coordinator = try mixedSaveCoordinator(command, turn: turn, cancellation: cancellation)
        let currentURI = try mixedSaveCurrentURI(captured, candidate: candidate)
        let lease = MixedSaveCallbackLease()
        lease.work = { [weak self] branch in
            guard let self else { throw Self.ownedSaveFailure }
            let checked = try self.requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation, editorAbsent: true)
            let recomputed = try self.mixedSaveCurrentURI(checked, candidate: candidate)
            guard (currentURI == nil && recomputed == nil) || currentURI.flatMap({ value in
                recomputed.map { Self.ownedEqual(value, $0) }
            }) == true else { throw Self.ownedSaveFailure }
            let outcome: String
            switch branch {
            case "referenced": outcome = "referenced"
            case "taskChanged": guard candidate.reason != "uncommitted-draft" else { throw Self.ownedSaveFailure }; outcome = "taskChanged"
            case "retire":
                switch binding.record {
                case .mixed(let record):
                    outcome = try coordinator.retireMixedSaveTarget(candidate, record: record, currentURI: currentURI, cancellation: cancellation)
                case .availability(let record):
                    guard currentURI == nil else { throw Self.ownedSaveFailure }
                    if case .borrowedAvailability = candidate.authority {
                        outcome = try coordinator.retireAvailabilitySaveTarget(candidate, record: record, cancellation: cancellation)
                    } else {
                        outcome = try self.durableAttachmentReferenceRetirement(targetURI: candidate.targetURI, cancellation: cancellation, retainDurableReference: true,
                            requireOwner: { _ = try self.requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation, editorAbsent: true) },
                            retire: { try coordinator.retireAvailabilitySaveTarget(candidate, record: record, cancellation: cancellation) })
                    }
                case .legacy: throw Self.ownedSaveFailure
                }
            default: throw Self.ownedSaveFailure
            }
            guard candidate.outcomes.contains(outcome) else { throw Self.ownedSaveFailure }
            _ = try self.requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation, editorAbsent: true)
            return outcome
        }
        let referenced: @convention(block) () -> String = { [weak lease] in lease?.enter("referenced") ?? "!MindwtrNativeError:Attachment Save callback is unavailable" }
        let changed: @convention(block) () -> String = { [weak lease] in lease?.enter("taskChanged") ?? "!MindwtrNativeError:Attachment Save callback is unavailable" }
        let retire: @convention(block) () -> String = { [weak lease] in lease?.enter("retire") ?? "!MindwtrNativeError:Attachment Save callback is unavailable" }
        var frame: [String: Any] = ["version": currentURI == nil ? 1 : 2,
                                  "envelopeJSON": captured.envelopeJSON, "candidateIndex": candidate.index]
        if let currentURI { frame["currentURI"] = currentURI }
        let input = try Self.ownedJSON(frame)
        guard input.utf8.count <= Self.ownedSaveMaximumBytes else { throw Self.ownedSaveFailure }
        invoking = true
        defer { lease.invalidate(); invoking = false; scheduleAttachmentIdle(immediate: true) }
        turn.runtime.exception = nil
        guard let referencedValue = JSValue(object: referenced, in: turn.runtime),
              let changedValue = JSValue(object: changed, in: turn.runtime),
              let retireValue = JSValue(object: retire, in: turn.runtime),
              turn.runtime.exception == nil else { throw Self.ownedSaveFailure }
        let returned = host.invokeMethod("attachmentFileEditSaveRetire", withArguments: [input, referencedValue, changedValue, retireValue])
        let threw = turn.runtime.exception != nil; turn.runtime.exception = nil
        guard !threw, lease.consumed, !lease.failed, let outcome = lease.outcome,
              let returned, returned.isString, let text = returned.toString(), text.utf8.count <= 1024,
              let value = try NativeJSON.jsonObject(with: Data(text.utf8)) as? [String: Any],
              Set(value.keys) == Set(["outcome"]), value["outcome"] as? String == outcome else { throw Self.ownedSaveFailure }
        _ = try requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation, editorAbsent: true)
        return outcome
    }
    private func clearMixedSave(_ command: PendingCommand, turn: MixedSaveTurn,
                                cancellation: NativeAttachmentCancellation, settled: Bool) throws {
        _ = try requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation, editorAbsent: settled, sidecarAbsent: settled)
        #if DEBUG
        try attachmentDraftHooks?.boundary?(.beforeSaveJournalClear)
        try faults?.journalRemove?()
        #endif
        _ = try requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation, editorAbsent: settled, sidecarAbsent: settled)
        try DurableFile.remove(journalURL)
        #if DEBUG
        try attachmentDraftHooks?.boundary?(.afterSaveJournalClear)
        #endif
        try requireMixedSaveOwner(turn, cancellation: cancellation)
        guard let current = pending, try ownedEncoded(current) == ownedEncoded(command), try ownedJournalIsAbsent(),
              try mixedSaveFileBinding(editorDrafts.url, maximumBytes: 3_000_000) == turn.editor else { throw Self.ownedSaveFailure }
        let captured = try mixedSaveJournal(command)
        if settled { guard captured.binding == nil else { throw Self.ownedSaveFailure } }
        else { guard let actual = captured.binding, turn.record?.matches(actual) == true else { throw Self.ownedSaveFailure } }
        pending = nil
    }
    private func hasSavedTaskFileHash(_ captured: MixedSaveJournal) throws -> Bool {
        guard captured.selection == .completeHash else { return false }
        guard let envelope = try NativeJSON.jsonObject(with: Data(captured.envelopeJSON.utf8)) as? [String: Any] else { throw Self.ownedSaveFailure }
        guard let request = envelope["request"] as? [String: Any], let owned = request["ownedDraft"] as? [String: Any],
              let history = owned["priorOperations"] as? [[String: Any]],
              let save = request["saveRequest"] as? [String: Any], let id = save["id"] as? String,
              let prepared = envelope["prepared"] as? [String: Any], let decision = prepared["decision"] as? [String: Any],
              let proof = decision["prepared"] as? [String: Any] else { throw Self.ownedSaveFailure }
        let after: [String: Any]?
        if decision["kind"] as? String == "changed" {
            after = ((proof["effect"] as? [String: Any])?["tasks"] as? [[String: Any]])?
                .compactMap { $0["after"] as? [String: Any] }.first { ($0["id"] as? String).map { Self.ownedEqual($0, id) } == true }
        } else { after = (proof["witness"] as? [String: Any])?["source"] as? [String: Any] }
        guard let after else { throw Self.ownedSaveFailure }
        let attachments = after["attachments"] as? [[String: Any]] ?? []
        return history.contains { entry in
            guard entry["kind"] as? String == "add", let operation = entry["operation"] as? [String: Any],
                  Self.isInteger(operation["version"], equalTo: 2), let id = operation["requestId"] as? String,
                  let hash = operation["sourceSha256"] as? String, let uri = operation["targetURI"] as? String else { return false }
            return attachments.contains { attachment in
                attachment["kind"] as? String == "file" && attachment["deletedAt"] == nil
                    && (attachment["id"] as? String).map { Self.ownedEqual($0, id) } == true
                    && (attachment["uri"] as? String).map { Self.ownedEqual($0, uri) } == true
                    && (attachment["fileHash"] as? String).map { Self.ownedEqual($0, hash) } == true
            }
        }
    }
    private func executeMixedSave(_ original: PendingCommand, cancellation: NativeAttachmentCancellation,
                                  turn supplied: MixedSaveTurn? = nil, firstInvocation: Bool = false) throws -> TerminalResult {
        var command = original
        var savedResult = try mixedSaveJournal(command, checkingNative: false).settlement?.resultJSON
        do {
            let turn = try supplied ?? mixedSaveTurn(command)
            if supplied == nil {
                // A warm uncertain progress write is owed before another action.
                if turn.journal == nil {
                    // A lost clear acknowledgment has only a warm retained
                    // settled owner. Recreate its exact journal before release.
                    try requireMixedSaveOwner(turn, cancellation: cancellation)
                    let captured = try mixedSaveJournal(command)
                    let settled = captured.settlement?.phase == "settled" && captured.binding == nil && turn.editor == nil
                    let unwrittenIntent = command.terminal == nil && captured.binding != nil && turn.editor != nil
                    guard settled || unwrittenIntent, try ownedJournalIsAbsent(), let current = pending,
                          try ownedEncoded(current) == ownedEncoded(command) else { throw Self.ownedSaveFailure }
                } else {
                    _ = try requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation, promotion: true,
                        proposedState: turn.validated?.settlement)
                }
                try persist(command, mixedGuard: { [unowned self] in
                    _ = try self.requireMixedSaveEvidence(command, turn: turn, cancellation: cancellation, state: turn.validated?.settlement)
                })
                guard let written = try mixedSaveFileBinding(journalURL, maximumBytes: Self.ownedSaveMaximumBytes),
                      written.bytes == (try ownedEncoded(command)) else { throw Self.ownedSaveFailure }
                turn.journal = written
                turn.acknowledged = command; turn.acknowledgedState = turn.validated?.settlement
            }
            _ = try requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation)
            let validated = try validateMixedSave(command)
            _ = try requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation)
            if command.terminal == nil {
                let captured = try requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation)
                guard let binding = captured.binding else { throw Self.ownedSaveFailure }
                let coordinator = try mixedSaveCoordinator(command, turn: turn, cancellation: cancellation)
                switch binding.record {
                case .mixed(let record): try coordinator.verifyMixedSavePublished(record, envelopeJSON: captured.envelopeJSON, selection: captured.selection, cancellation: cancellation)
                case .availability(let record): try coordinator.verifyAvailabilitySavePublished(record, envelopeJSON: captured.envelopeJSON, cancellation: cancellation)
                case .legacy: throw Self.ownedSaveFailure
                }
                #if DEBUG
                try attachmentDraftHooks?.boundary?(.beforeSaveCommit)
                #endif
                _ = try requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation)
                let result: String
                do { result = try invoke(Self.mixedSaveMethod, arguments: [captured.envelopeJSON]) }
                catch let failure as HostFailure {
                    guard firstInvocation, isDefiniteRejection(failure.message, method: Self.mixedSaveMethod) else { throw failure }
                    command.terminal = .rejected(failure.message)
                    try persistMixedSaveProgress(command, turn: turn, cancellation: cancellation, before: .beforeSaveTerminal, after: .afterSaveTerminal)
                    return try finishMixedSaveRejection(command, turn: turn, cancellation: cancellation)
                }
                #if DEBUG
                try attachmentDraftHooks?.boundary?(.afterSaveCommit)
                #endif
                _ = try requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation)
                _ = try validateMixedSave(command, result: result)
                _ = try requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation)
                let state = MixedSaveSettlement(phase: "domainSaved", resultJSON: result,
                    targets: Array(repeating: nil, count: validated.1.count), stages: Array(repeating: nil, count: captured.stages.count))
                command.terminal = .success(try mixedSaveStateJSON(state, stages: captured.stages)); savedResult = result
                try persistMixedSaveProgress(command, turn: turn, cancellation: cancellation, before: .beforeSaveTerminal, after: .afterSaveTerminal)
                if captured.selection.isComplete { rememberConfirmedTaskCancellation(command) }
                _ = try? invoke("attachmentDraftAcknowledged", arguments: [captured.selection == .completeAvailability ? "availability-save" : captured.selection.isComplete ? "complete-save" : "mixed-save", "domainSaved"])
                _ = try requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation)
            }
            if case .rejected = command.terminal { return try finishMixedSaveRejection(command, turn: turn, cancellation: cancellation) }
            guard var state = try mixedSaveJournal(command).settlement else { throw Self.ownedSaveFailure }
            let captured = try requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation)
            // Retained terminal replay validates and re-ACKs the exact complete
            // cancellation before cleanup; preparation/unknown SQL grants none.
            if captured.selection.isComplete { rememberConfirmedTaskCancellation(command) }
            if state.phase == "domainSaved", try hasSavedTaskFileHash(captured) {
                _ = try? invoke("attachmentDraftAcknowledged", arguments: ["task-file-hash", "saved"])
                _ = try requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation)
            }
            if state.phase != "settled" {
                #if DEBUG
                try attachmentDraftHooks?.boundary?(.beforeSaveEditorDetach)
                try faults?.editorDraftRemove?()
                #endif
                _ = try requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation)
                try editorDrafts.removeOwnedSaveMatching(expected: captured.snapshot, attempt: captured.attempt)
                turn.editor = nil
                #if DEBUG
                try attachmentDraftHooks?.boundary?(.afterSaveEditorDetach)
                #endif
                _ = try requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation, editorAbsent: true)
                for candidate in validated.1 where state.targets[candidate.index] == nil {
                    #if DEBUG
                    try attachmentDraftHooks?.boundary?(.beforeSaveTarget(candidate.index))
                    #endif
                    _ = try requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation, editorAbsent: true)
                    let outcome = try mixedSaveTargetHandoff(command, turn: turn, candidate: candidate, cancellation: cancellation)
                    #if DEBUG
                    try attachmentDraftHooks?.boundary?(.afterSaveTarget(candidate.index))
                    #endif
                    _ = try requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation, editorAbsent: true)
                    state.targets[candidate.index] = outcome
                    command.terminal = .success(try mixedSaveStateJSON(state, stages: captured.stages))
                    try persistMixedSaveProgress(command, turn: turn, cancellation: cancellation, before: .beforeSaveProgress, after: .afterSaveProgress)
                }
                guard let binding = captured.binding else { throw Self.ownedSaveFailure }
                let stageOperations: [NativeAttachmentDraftStore.Operation]
                switch binding.record {
                case .mixed(let record): stageOperations = NativeAttachmentDraftCoordinator.mixedSaveAdds(record)
                case .availability(let record): stageOperations = try record.operations.compactMap { op in
                    if case .owned = op.resource { return try NativeAttachmentDraftCoordinator.availabilityOwnedOperation(op) }; return nil
                }
                case .legacy: throw Self.ownedSaveFailure
                }
                for index in stageOperations.indices where state.stages[index] == nil {
                    #if DEBUG
                    try attachmentDraftHooks?.boundary?(.beforeSaveStage(index))
                    #endif
                    _ = try requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation, editorAbsent: true)
                    let outcome = try mixedSaveCoordinator(command, turn: turn, cancellation: cancellation).retireMixedSaveStage(stageOperations[index], cancellation: cancellation)
                    #if DEBUG
                    try attachmentDraftHooks?.boundary?(.afterSaveStage(index))
                    #endif
                    _ = try requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation, editorAbsent: true)
                    state.stages[index] = outcome
                    command.terminal = .success(try mixedSaveStateJSON(state, stages: captured.stages))
                    try persistMixedSaveProgress(command, turn: turn, cancellation: cancellation, before: .beforeSaveProgress, after: .afterSaveProgress)
                }
                state.phase = "settled"
                command.terminal = .success(try mixedSaveStateJSON(state, stages: captured.stages))
                try persistMixedSaveProgress(command, turn: turn, cancellation: cancellation, before: .beforeSaveSettled, after: .afterSaveSettled)
            }
            // A settled replay performs no file jobs, including private stages.
            _ = try requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation, editorAbsent: true)
            if let relocation = captured.relocation, relocation.containerComponentIndex != nil {
                try requireMixedSaveRelocation(relocation)
                _ = try? invoke("attachmentDraftAcknowledged", arguments: ["container-relocation", "confirmed"])
                _ = try requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation, editorAbsent: true)
                try requireMixedSaveRelocation(relocation)
            }
            #if DEBUG
            try attachmentDraftHooks?.boundary?(.beforeSaveRelease)
            #endif
            _ = try requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation, editorAbsent: true)
            if captured.selection == .completeAvailability {
                try NativeAttachmentDraftStore(databaseURL: databaseURL).releaseSavedAvailabilityMatching(fingerprint: captured.fingerprint)
            } else {
                try NativeAttachmentDraftStore(databaseURL: databaseURL).releaseSavedMixedMatching(fingerprint: captured.fingerprint,
                    allowsEmptyHistory: captured.selection.isComplete)
            }
            #if DEBUG
            try attachmentDraftHooks?.boundary?(.afterSaveRelease)
            #endif
            _ = try requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation, editorAbsent: true, sidecarAbsent: true)
            try clearMixedSave(command, turn: turn, cancellation: cancellation, settled: true)
            _ = try? invoke("attachmentDraftAcknowledged", arguments: [captured.selection == .completeAvailability ? "availability-save" : captured.selection.isComplete ? "complete-save" : "mixed-save", "settled"])
            return .success(state.resultJSON)
        } catch let rejected as CoreHostRejection { throw rejected }
        catch {
            if let savedResult { throw CoreHostAttachmentCleanupPending(resultJSON: savedResult) }
            throw Self.ownedSaveFailure
        }
    }
    private func finishMixedSaveRejection(_ command: PendingCommand, turn: MixedSaveTurn,
                                          cancellation: NativeAttachmentCancellation) throws -> TerminalResult {
        guard let terminal = command.terminal, case .rejected = terminal else { throw Self.ownedSaveFailure }
        let captured = try requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation)
        #if DEBUG
        try attachmentDraftHooks?.boundary?(.beforeSaveThaw)
        #endif
        _ = try requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation)
        try editorDrafts.thawOwnedSaveMatching(expected: captured.snapshot, attempt: captured.attempt)
        turn.editor = try mixedSaveFileBinding(editorDrafts.url, maximumBytes: 3_000_000)
        #if DEBUG
        try attachmentDraftHooks?.boundary?(.afterSaveThaw)
        #endif
        _ = try requireMixedSaveAuthority(command, turn: turn, cancellation: cancellation)
        try clearMixedSave(command, turn: turn, cancellation: cancellation, settled: false)
        return terminal
    }

    private func validateOwnedSaveAcknowledgement(_ command: PendingCommand, value: String? = nil) throws -> String {
        let captured = try ownedSaveJournal(command, checkingNative: false)
        let encoded = try invoke("attachmentOwnedSaveValidate", arguments: [captured.envelopeJSON])
        guard let validation = try NativeJSON.jsonObject(with: Data(encoded.utf8)) as? [String: Any],
              Set(validation.keys) == Set(["version", "kind", "result"]), Self.isInteger(validation["version"], equalTo: 1),
              validation["kind"] as? String == "owned-editor-file-add-save",
              let expected = validation["result"] as? [String: Any], Set(expected.keys) == Set(["id", "draft"]),
              let id = expected["id"] as? String, Self.ownedEqual(id, captured.snapshot.taskID), expected["draft"] is [String: Any] else {
            throw Self.ownedSaveFailure
        }
        if let value {
            guard let acknowledged = try NativeJSON.jsonObject(with: Data(value.utf8)) as? [String: Any],
                  Set(acknowledged.keys) == Set(["id", "draft"]), Self.equalJSON(expected, acknowledged) else { throw Self.ownedSaveFailure }
        }
        return try Self.ownedJSON(expected)
    }

    private func ownedSaveCoordinatorForWork() throws -> NativeAttachmentDraftCoordinator {
        dispatchPrecondition(condition: .onQueue(queue))
        guard started, !closed, lockFD >= 0, let jobs = attachmentJobs else { throw Self.ownedSaveFailure }
        let coordinator = try NativeAttachmentDraftCoordinator(databaseURL: databaseURL, jobs: jobs) { [unowned self] name, args in
            try self.invoke(name, arguments: args)
        }
        #if DEBUG
        coordinator.hooks = attachmentDraftHooks
        #endif
        return coordinator
    }

    private func preflightOwnedSave(_ command: PendingCommand, snapshot: EditorDraftSnapshot, result: String) throws {
        guard let attempt = command.editorDraft else { throw Self.ownedSaveFailure }
        try editorDrafts.preflightOwnedSave(expected: snapshot, attempt: attempt)
        _ = try ownedSaveJournal(command, checkingNative: false)
        var success = command; success.terminal = .success(result)
        var rejected = command
        // Each ASCII control byte has the maximum six-byte JSON escaping cost.
        // Reserve a full bounded rejection rather than truncating future evidence.
        rejected.terminal = .rejected(String(repeating: "\u{0000}", count: Self.ownedSaveRejectionBytes))
        for candidate in [command, success, rejected] {
            guard try JSONEncoder().encode(candidate).count <= Self.ownedSaveMaximumBytes else { throw Self.ownedSaveFailure }
        }
    }

    private func requireUnfrozenOwnedSave(_ prepared: NativeAttachmentDraftCoordinator.OwnedSavePreparation) throws {
        guard let record = try NativeAttachmentDraftStore(databaseURL: databaseURL).read(),
              Self.ownedEqual(try NativeAttachmentDraftStore.ownedSaveFingerprint(record), prepared.fingerprint),
              let current = try editorDrafts.read(), current.attempt == nil,
              Self.ownedEqual(current.snapshot, prepared.snapshot) else { throw Self.ownedSaveFailure }
    }

    private func requireOwnedSaveInvocation(_ command: PendingCommand) throws -> OwnedSaveJournal {
        try requireOwnedJournalOnDisk(command)
        let captured = try ownedSaveJournal(command)
        guard let record = captured.record else { throw Self.ownedSaveFailure }
        try ownedSaveCoordinatorForWork().verifyOwnedSavePublished(record)
        try requireOwnedJournalOnDisk(command)
        return try ownedSaveJournal(command)
    }

    private func ownedJournalIsAbsent() throws -> Bool {
        var info = stat()
        if lstat(journalURL.path, &info) == 0 { return false }
        guard errno == ENOENT else { throw Self.ownedSaveFailure }
        return true
    }

    private static func ownedDiscardUUID(_ value: Any?) -> String? {
        guard let value = value as? String, UUID(uuidString: value)?.uuidString.lowercased() == value else { return nil }
        return value
    }
    private func ownedDiscardJournal(_ command: PendingCommand, checkingNative: Bool = true) throws -> OwnedDiscardJournal {
        guard command.version == 2, command.method == Self.ownedDiscardMethod, command.editorDraft == nil,
              try JSONEncoder().encode(command).count <= Self.ownedSaveMaximumBytes,
              command.argumentsJSON.utf8.count <= Self.ownedSaveMaximumBytes,
              let args = try NativeJSON.jsonObject(with: Data(command.argumentsJSON.utf8)) as? [String], args.count == 1,
              let wrapper = try NativeJSON.jsonObject(with: Data(args[0].utf8)) as? [String: Any] else { throw Self.ownedDiscardFailure }
        if Self.isInteger(wrapper["version"], equalTo: 5) || Self.isInteger(wrapper["version"], equalTo: 6) || Self.isInteger(wrapper["version"], equalTo: 7) {
            return try ownedMixedDiscardJournal(command, wrapper: wrapper, checkingNative: checkingNative)
        }
        guard Set(wrapper.keys) == Set(["version", "sessionID", "requestId", "recordSHA256", "operationIDs"]),
              Self.isInteger(wrapper["version"], equalTo: 1) || Self.isInteger(wrapper["version"], equalTo: 2)
                  || Self.isInteger(wrapper["version"], equalTo: 3) || Self.isInteger(wrapper["version"], equalTo: 4),
              let session = Self.ownedDiscardUUID(wrapper["sessionID"]), let id = Self.ownedDiscardUUID(wrapper["requestId"]),
              let fingerprint = wrapper["recordSHA256"] as? String, fingerprint.utf8.count == 64,
              fingerprint.utf8.allSatisfy({ (48...57).contains($0) || (97...102).contains($0) }),
              let ids = wrapper["operationIDs"] as? [String], ids.count <= 128, Set(ids).count == ids.count,
              ids.allSatisfy({ Self.ownedDiscardUUID($0) != nil && $0 != id }) else { throw Self.ownedDiscardFailure }
        let version = Self.isInteger(wrapper["version"], equalTo: 1) ? 1 : Self.isInteger(wrapper["version"], equalTo: 2) ? 2
            : Self.isInteger(wrapper["version"], equalTo: 3) ? 3 : 4
        guard version == 1 || !ids.isEmpty else { throw Self.ownedDiscardFailure }
        if let terminal = command.terminal {
            guard case .success(let value) = terminal else { throw Self.ownedDiscardFailure }
            try validateOwnedDiscardResult(value, version: version, session: session, requestId: id, operationIDs: ids)
        }
        let record = checkingNative ? try NativeAttachmentDraftStore(databaseURL: databaseURL).read() : nil
        if checkingNative {
            guard try editorDrafts.read() == nil else { throw Self.ownedDiscardFailure }
            if let record {
                guard Self.ownedEqual(try NativeAttachmentDraftStore.ownedDiscardFingerprint(record), fingerprint),
                      Self.ownedEqual(record.session.sessionID, session), record.discard.map({ Self.ownedEqual($0.requestId, id) }) == true,
                      record.operations.map(\.requestId) == ids,
                      try NativeAttachmentDraftCoordinator.ownedDiscardVersion(record) == version else { throw Self.ownedDiscardFailure }
            } else {
                guard case .success = command.terminal else { throw Self.ownedDiscardFailure }
            }
        }
        return OwnedDiscardJournal(version: version, session: session, requestId: id, fingerprint: fingerprint, operationIDs: ids, record: record)
    }

    private static func mixedDiscardOperations(_ record: NativeAttachmentDraftStore.MixedRecord) -> [MixedDiscardOperation] {
        record.operations.map { entry in
            switch entry {
            case .add(let op): return .init(kind: "add", requestId: op.requestId, phase: op.phase.rawValue)
            case .remove(let op): return .init(kind: "remove", requestId: op.requestId, phase: op.phase.rawValue)
            }
        }
    }
    private func ownedMixedDiscardJournal(_ command: PendingCommand, wrapper: [String: Any],
                                          checkingNative: Bool) throws -> OwnedDiscardJournal {
        let version = Self.isInteger(wrapper["version"], equalTo: 7) ? 7 : Self.isInteger(wrapper["version"], equalTo: 6) ? 6 : 5
        let historyVersion = version == 7 ? 5 : version == 6 ? 4 : 3
        guard Set(wrapper.keys) == Set(["version", "historyVersion", "sessionID", "requestId", "recordSHA256", "operations"]),
              Self.isInteger(wrapper["historyVersion"], equalTo: historyVersion),
              let session = Self.ownedDiscardUUID(wrapper["sessionID"]), let id = Self.ownedDiscardUUID(wrapper["requestId"]),
              let fingerprint = wrapper["recordSHA256"] as? String, fingerprint.utf8.count == 64,
              fingerprint.utf8.allSatisfy({ (48...57).contains($0) || (97...102).contains($0) }),
              let raw = wrapper["operations"] as? [[String: Any]], raw.count <= 128 else { throw Self.ownedDiscardFailure }
        var used = Set([id]), operations: [MixedDiscardOperation] = []
        for (index, entry) in raw.enumerated() {
            guard let requestId = Self.ownedDiscardUUID(entry["requestId"]), used.insert(requestId).inserted,
                  let phase = entry["phase"] as? String, index == raw.count - 1 || phase == "checkpointed" else { throw Self.ownedDiscardFailure }
            if version == 7 {
                guard Set(entry.keys) == Set(["kind", "requestId", "phase", "attachmentId", "targetURI", "resource", "candidate"]),
                      entry["kind"] as? String == "availability", NativeAttachmentDraftStore.Phase(rawValue: phase) != nil,
                      let attachmentId = entry["attachmentId"] as? String, !attachmentId.isEmpty, attachmentId.utf16.count <= 500, attachmentId.utf8.count <= 2000,
                      let resource = entry["resource"] as? String, ["none", "borrowed", "owned"].contains(resource),
                      Self.isBoolean(entry["candidate"]), let candidate = entry["candidate"] as? Bool,
                      entry["targetURI"] is NSNull || entry["targetURI"] is String else { throw Self.ownedDiscardFailure }
                let target = entry["targetURI"] as? String
                if resource == "none" { guard target == nil, !candidate, ["intent", "resultDurable", "checkpointed"].contains(phase) else { throw Self.ownedDiscardFailure } }
                else { guard let target, !target.isEmpty, target.utf8.count <= 16 * 1024 else { throw Self.ownedDiscardFailure } }
                if resource == "borrowed" { guard ["intent", "resultDurable", "checkpointed"].contains(phase) else { throw Self.ownedDiscardFailure } }
                operations.append(.init(kind: "availability", requestId: requestId, phase: phase, attachmentId: attachmentId,
                    targetURI: target, resource: resource, candidate: candidate))
            } else {
                guard Set(entry.keys) == Set(["kind", "requestId", "phase"]), let kind = entry["kind"] as? String,
                      ["add", "remove"].contains(kind), (kind == "add" ? NativeAttachmentDraftStore.Phase(rawValue: phase) != nil
                        : NativeAttachmentDraftStore.RemovePhase(rawValue: phase) != nil) else { throw Self.ownedDiscardFailure }
                operations.append(.init(kind: kind, requestId: requestId, phase: phase))
            }
        }
        let captured = OwnedDiscardJournal(version: version, session: session, requestId: id, fingerprint: fingerprint,
            operationIDs: operations.map(\.requestId), record: nil, mixedOperations: operations)
        if let terminal = command.terminal {
            guard case .success(let value) = terminal else { throw Self.ownedDiscardFailure }
            try validateMixedDiscardResult(value, captured: captured)
        }
        guard checkingNative else { return captured }
        guard try mixedSaveFileBinding(editorDrafts.url, maximumBytes: 3_000_000) == nil else { throw Self.ownedDiscardFailure }
        let binding = try NativeAttachmentDraftStore(databaseURL: databaseURL).readVersioned()
        if let binding {
            if version == 7 {
                guard case .availability(let record) = binding.record,
                      Self.ownedEqual(try NativeAttachmentDraftStore.ownedAvailabilityDiscardFingerprint(record), fingerprint),
                      Self.ownedEqual(record.session.sessionID, session), record.discard.map({ Self.ownedEqual($0.requestId, id) }) == true,
                      Self.availabilityDiscardOperations(record, candidateIDs: Set(operations.filter { $0.candidate == true }.map(\.requestId))) == operations else { throw Self.ownedDiscardFailure }
            } else {
                guard case .mixed(let record) = binding.record, record.version == historyVersion,
                      Self.ownedEqual(try NativeAttachmentDraftStore.ownedMixedDiscardFingerprint(record), fingerprint),
                      Self.ownedEqual(record.session.sessionID, session), record.discard.map({ Self.ownedEqual($0.requestId, id) }) == true,
                      Self.mixedDiscardOperations(record) == operations else { throw Self.ownedDiscardFailure }
                _ = try NativeAttachmentDraftCoordinator.mixedDiscardAdds(record)
            }
        } else { guard case .success = command.terminal else { throw Self.ownedDiscardFailure } }
        return .init(version: version, session: session, requestId: id, fingerprint: fingerprint, operationIDs: captured.operationIDs,
            record: nil, mixedOperations: operations, mixedBinding: binding)
    }
    private func validateMixedDiscardResult(_ value: String, captured: OwnedDiscardJournal) throws {
        guard value.utf8.count <= 64 * 1024, let expected = captured.mixedOperations,
              let result = try NativeJSON.jsonObject(with: Data(value.utf8)) as? [String: Any],
              Set(result.keys) == Set(["version", "historyVersion", "status", "sessionID", "requestId", "operations"]),
              Self.isInteger(result["version"], equalTo: captured.version), Self.isInteger(result["historyVersion"], equalTo: captured.version == 7 ? 5 : captured.version == 6 ? 4 : 3),
              result["status"] as? String == "discarded",
              let session = result["sessionID"] as? String, Self.ownedEqual(session, captured.session),
              let id = result["requestId"] as? String, Self.ownedEqual(id, captured.requestId),
              let operations = result["operations"] as? [[String: Any]], operations.count == expected.count else { throw Self.ownedDiscardFailure }
        for (actual, op) in zip(operations, expected) {
            guard actual["kind"] as? String == op.kind, actual["requestId"] as? String == op.requestId else { throw Self.ownedDiscardFailure }
            if op.kind == "availability" {
                let targets: Set<String>
                if op.candidate == false || (op.resource == "owned" && ["intent", "stagePrepared", "stageFilled"].contains(op.phase)) { targets = ["untouched"] }
                else if op.resource == "borrowed" { targets = ["notOwned", "referenced"] }
                else if op.resource == "owned" { targets = ["removed", "absent", "referenced"] }
                else { throw Self.ownedDiscardFailure }
                let stages: Set<String> = op.resource != "owned" || op.phase == "intent" ? ["unclaimed"] : ["removed", "missing"]
                guard Set(actual.keys) == Set(["kind", "requestId", "target", "stage"]),
                      let target = actual["target"] as? String, targets.contains(target),
                      let stage = actual["stage"] as? String, stages.contains(stage) else { throw Self.ownedDiscardFailure }
            } else if op.kind == "remove" {
                guard Set(actual.keys) == Set(["kind", "requestId", "disposition"]),
                      actual["disposition"] as? String == "metadataOnly" else { throw Self.ownedDiscardFailure }
            } else {
                let unpublished = ["intent", "stagePrepared", "stageFilled"].contains(op.phase)
                guard Set(actual.keys) == Set(["kind", "requestId", "target", "stage"]),
                      let target = actual["target"] as? String,
                      (unpublished ? ["untouched"] : ["removed", "absent", "referenced"]).contains(target),
                      let stage = actual["stage"] as? String,
                      (op.phase == "intent" ? ["unclaimed"] : ["removed", "missing"]).contains(stage) else { throw Self.ownedDiscardFailure }
            }
        }
    }
    private func validateOwnedDiscardResult(_ value: String, version: Int, session: String, requestId: String, operationIDs: [String]) throws {
        guard value.utf8.count <= 64 * 1024,
              let result = try NativeJSON.jsonObject(with: Data(value.utf8)) as? [String: Any],
              Set(result.keys) == Set(["version", "status", "sessionID", "requestId", "operations"]),
              Self.isInteger(result["version"], equalTo: version), result["status"] as? String == (version == 3 ? "discarded" : "released"),
              let actualSession = result["sessionID"] as? String, Self.ownedEqual(actualSession, session),
              let actualID = result["requestId"] as? String, Self.ownedEqual(actualID, requestId),
              let operations = result["operations"] as? [[String: Any]], operations.count == operationIDs.count else { throw Self.ownedDiscardFailure }
        for (index, pair) in zip(operations, operationIDs).enumerated() {
            let (operation, id) = pair
            let last = index == operationIDs.count - 1
            let targets = version >= 2 && last ? ["untouched"] : ["removed", "absent", "referenced"]
            let stages = version == 3 && last ? ["unclaimed"] : ["removed", "missing"]
            guard Set(operation.keys) == Set(["requestId", "target", "stage"]), operation["requestId"] as? String == id,
                  let target = operation["target"] as? String, targets.contains(target),
                  let stage = operation["stage"] as? String, stages.contains(stage) else { throw Self.ownedDiscardFailure }
        }
    }
    private func decodeOwnedDiscardJournal(_ data: Data, checkingNative: Bool) throws -> PendingCommand {
        guard data.count <= Self.ownedSaveMaximumBytes,
              let raw = try NativeJSON.jsonObject(with: data) as? [String: Any],
              Set(raw.keys) == Set(["version", "method", "argumentsJSON"] + (raw["terminal"] == nil ? [] : ["terminal"])),
              Self.isInteger(raw["version"], equalTo: 2),
              let command = try? JSONDecoder().decode(PendingCommand.self, from: data), command.method == Self.ownedDiscardMethod else { throw Self.ownedDiscardFailure }
        if let terminal = raw["terminal"] {
            guard let object = terminal as? [String: Any], Set(object.keys) == Set(["success"]),
                  let body = object["success"] as? [String: Any], Set(body.keys) == Set(["_0"]), body["_0"] is String else { throw Self.ownedDiscardFailure }
        }
        _ = try ownedDiscardJournal(command, checkingNative: checkingNative)
        return command
    }
    private func ownedDiscardIdentity(_ url: URL) throws -> OwnedDiscardIdentity? {
        try Self.bindingIdentity(url)
    }
    private static func bindingIdentity(_ url: URL) throws -> OwnedDiscardIdentity? {
        var info = stat()
        if lstat(url.path, &info) < 0 {
            if errno == ENOENT { return nil }
            throw Self.ownedDiscardFailure
        }
        guard (info.st_mode & S_IFMT) == S_IFREG, info.st_nlink == 1 else { throw Self.ownedDiscardFailure }
        return .init(device: info.st_dev, inode: info.st_ino)
    }
    private func ownedDiscardTurn(_ command: PendingCommand) throws -> OwnedDiscardTurn {
        guard started, !closed, lockFD >= 0, let context else { throw Self.ownedDiscardFailure }
        if try ownedDiscardJournal(command, checkingNative: false).version >= 5 {
            let captured = try ownedDiscardJournal(command)
            guard let jobs = attachmentJobs else { throw Self.ownedDiscardFailure }
            let turn = OwnedDiscardTurn(generation: attachmentGeneration, runtime: context,
                recordIdentity: nil, jobs: jobs, mixedBinding: captured.mixedBinding)
            turn.mixedValidated = captured
            turn.mixedJournal = try mixedSaveFileBinding(journalURL, maximumBytes: Self.ownedSaveMaximumBytes)
            if let journal = turn.mixedJournal {
                let actual = try decodeOwnedDiscardJournal(journal.bytes, checkingNative: true)
                var before = actual, after = command; before.terminal = nil; after.terminal = nil
                guard try ownedEncoded(before) == ownedEncoded(after) else { throw Self.ownedDiscardFailure }
                if actual.terminal != nil {
                    guard try ownedEncoded(actual) == ownedEncoded(command) else { throw Self.ownedDiscardFailure }
                }
                turn.mixedAcknowledged = actual
            } else if case .success = command.terminal {
                // A lost journal-clear acknowledgment may leave only the exact
                // warm validated terminal. Re-persist it before release/clear;
                // this grants no nonterminal or attachment-job permission.
                guard let current = pending, try ownedEncoded(current) == ownedEncoded(command) else { throw Self.ownedDiscardFailure }
                turn.mixedAcknowledged = command
            }
            return turn
        }
        let identity = try ownedDiscardIdentity(NativeAttachmentDraftStore(databaseURL: databaseURL).url)
        let captured = try ownedDiscardJournal(command)
        guard (captured.record == nil) == (identity == nil),
              try ownedDiscardIdentity(NativeAttachmentDraftStore(databaseURL: databaseURL).url) == identity else { throw Self.ownedDiscardFailure }
        return .init(generation: attachmentGeneration, runtime: context, recordIdentity: identity)
    }
    private func requireOwnedDiscardAuthority(_ command: PendingCommand, turn: OwnedDiscardTurn,
                                             cancellation: NativeAttachmentCancellation,
                                             terminalPromotion: Bool = false, sidecarAbsent: Bool = false) throws -> OwnedDiscardJournal {
        if turn.mixedValidated != nil {
            return try requireMixedDiscardAuthority(command, turn: turn, cancellation: cancellation,
                promotion: terminalPromotion, sidecarAbsent: sidecarAbsent)
        }
        dispatchPrecondition(condition: .onQueue(queue))
        try cancellation.check()
        guard started, !closed, lockFD >= 0, attachmentGeneration == turn.generation, context === turn.runtime,
              let current = pending, try ownedEncoded(current) == ownedEncoded(command) else { throw Self.ownedDiscardFailure }
        if terminalPromotion { try requireOwnedJournalWriteIdentity(command) }
        else { try requireOwnedJournalOnDisk(command) }
        guard let identity = try ownedDiscardIdentity(journalURL), identity == turn.journalIdentity else { throw Self.ownedDiscardFailure }
        let captured = try ownedDiscardJournal(command)
        let actualIdentity = try ownedDiscardIdentity(NativeAttachmentDraftStore(databaseURL: databaseURL).url)
        if captured.record != nil {
            guard actualIdentity == turn.recordIdentity else { throw Self.ownedDiscardFailure }
        } else { guard actualIdentity == nil else { throw Self.ownedDiscardFailure } }
        if sidecarAbsent { guard captured.record == nil else { throw Self.ownedDiscardFailure } }
        return captured
    }
    private func ownedDiscardResult(_ captured: OwnedDiscardJournal, operations: [[String: String]]) throws -> String {
        if captured.version >= 5 {
            let value = try Self.ownedJSON(["version": captured.version, "historyVersion": captured.version == 7 ? 5 : captured.version == 6 ? 4 : 3, "status": "discarded",
                "sessionID": captured.session, "requestId": captured.requestId, "operations": operations] as [String: Any])
            try validateMixedDiscardResult(value, captured: captured)
            return value
        }
        let value = try Self.ownedJSON(["version": captured.version, "status": captured.version == 3 ? "discarded" : "released", "sessionID": captured.session,
            "requestId": captured.requestId, "operations": operations] as [String: Any])
        try validateOwnedDiscardResult(value, version: captured.version, session: captured.session, requestId: captured.requestId, operationIDs: captured.operationIDs)
        return value
    }
    private func preflightOwnedDiscard(_ command: PendingCommand) throws {
        let captured = try ownedDiscardJournal(command, checkingNative: false)
        if let mixed = captured.mixedOperations {
            let reserved = try ownedDiscardResult(captured, operations: mixed.map { op in
                if op.kind == "availability" {
                    return ["kind": "availability", "requestId": op.requestId,
                        "target": op.candidate == false || (op.resource == "owned" && ["intent", "stagePrepared", "stageFilled"].contains(op.phase)) ? "untouched" : "referenced",
                        "stage": op.resource != "owned" || op.phase == "intent" ? "unclaimed" : "removed"]
                }
                if op.kind == "remove" { return ["kind": "remove", "requestId": op.requestId, "disposition": "metadataOnly"] }
                return ["kind": "add", "requestId": op.requestId,
                    "target": ["intent", "stagePrepared", "stageFilled"].contains(op.phase) ? "untouched" : "referenced",
                    "stage": op.phase == "intent" ? "unclaimed" : "removed"]
            })
            var terminal = command; terminal.terminal = .success(reserved)
            for candidate in [command, terminal] {
                guard try ownedEncoded(candidate).count <= Self.ownedSaveMaximumBytes else { throw Self.ownedDiscardFailure }
            }
            return
        }
        let reserved = try ownedDiscardResult(captured, operations: captured.operationIDs.enumerated().map { index, id in
            ["requestId": id, "target": captured.version >= 2 && index == captured.operationIDs.count - 1 ? "untouched" : "referenced",
                "stage": captured.version == 3 && index == captured.operationIDs.count - 1 ? "unclaimed" : "removed"]
        })
        var terminal = command; terminal.terminal = .success(reserved)
        for candidate in [command, terminal] {
            guard try JSONEncoder().encode(candidate).count <= Self.ownedSaveMaximumBytes else { throw Self.ownedDiscardFailure }
        }
    }

    private func ownedDiscardCommand(_ record: NativeAttachmentDraftStore.Record) throws -> PendingCommand {
        guard let discard = record.discard else { throw Self.ownedDiscardFailure }
        let wrapper = try Self.ownedJSON(["version": NativeAttachmentDraftCoordinator.ownedDiscardVersion(record),
            "sessionID": record.session.sessionID, "requestId": discard.requestId,
            "recordSHA256": NativeAttachmentDraftStore.ownedDiscardFingerprint(record),
            "operationIDs": record.operations.map(\.requestId)] as [String: Any])
        return PendingCommand(version: 2, method: Self.ownedDiscardMethod,
            argumentsJSON: String(decoding: try JSONEncoder().encode([wrapper]), as: UTF8.self))
    }
    private func requireUnjournaledDiscardOwner(_ turn: OwnedDiscardTurn, cancellation: NativeAttachmentCancellation) throws {
        dispatchPrecondition(condition: .onQueue(queue))
        try cancellation.check()
        guard started, !closed, !recoveryActivationPending, lockFD >= 0, attachmentGeneration == turn.generation,
              context === turn.runtime, pending == nil, try ownedJournalIsAbsent(), try editorDrafts.read() == nil else {
              throw Self.ownedDiscardFailure
        }
        if let jobs = turn.jobs {
            guard attachmentJobs === jobs, try mixedSaveFileBinding(editorDrafts.url, maximumBytes: 3_000_000) == nil else { throw Self.ownedDiscardFailure }
        }
    }
    private func requireUnjournaledDiscard(_ command: PendingCommand, turn: OwnedDiscardTurn,
                                          cancellation: NativeAttachmentCancellation) throws {
        try requireUnjournaledDiscardOwner(turn, cancellation: cancellation)
        if turn.mixedValidated != nil {
            guard let binding = turn.mixedBinding,
                  let actual = try mixedSaveFileBinding(NativeAttachmentDraftStore(databaseURL: databaseURL).url, maximumBytes: Self.ownedSaveMaximumBytes),
                  actual.bytes == binding.bytes, UInt64(actual.identity.device) == binding.device,
                  UInt64(actual.identity.inode) == binding.inode else { throw Self.ownedDiscardFailure }
            return
        }
        _ = try ownedDiscardJournal(command)
        guard try ownedDiscardIdentity(NativeAttachmentDraftStore(databaseURL: databaseURL).url) == turn.recordIdentity else {
            throw Self.ownedDiscardFailure
        }
    }

    private func ownedMixedDiscardCommand(_ record: NativeAttachmentDraftStore.MixedRecord) throws -> PendingCommand {
        guard let discard = record.discard else { throw Self.ownedDiscardFailure }
        let wrapper = try Self.ownedJSON(["version": record.version == 4 ? 6 : 5, "historyVersion": record.version, "sessionID": record.session.sessionID,
            "requestId": discard.requestId, "recordSHA256": NativeAttachmentDraftStore.ownedMixedDiscardFingerprint(record),
            "operations": Self.mixedDiscardOperations(record).map(\.object)] as [String: Any])
        return PendingCommand(version: 2, method: Self.ownedDiscardMethod, argumentsJSON: try Self.ownedJSON([wrapper]))
    }

    private static func availabilityDiscardOperations(_ record: NativeAttachmentDraftStore.AvailabilityRecord,
                                                      candidateIDs: Set<String>) -> [MixedDiscardOperation] {
        record.operations.map { op in
            let resource: String
            switch op.resource { case .none: resource = "none"; case .borrowed: resource = "borrowed"; case .owned: resource = "owned" }
            return .init(kind: "availability", requestId: op.requestId, phase: op.phase.rawValue,
                attachmentId: op.attachmentId, targetURI: op.targetURI, resource: resource, candidate: candidateIDs.contains(op.requestId))
        }
    }
    private func ownedAvailabilityDiscardCommand(_ record: NativeAttachmentDraftStore.AvailabilityRecord,
                                                 candidates: [NativeAttachmentDraftStore.AvailabilityOperation]) throws -> PendingCommand {
        guard let discard = record.discard else { throw Self.ownedDiscardFailure }
        let wrapper = try Self.ownedJSON(["version": 7, "historyVersion": 5, "sessionID": record.session.sessionID,
            "requestId": discard.requestId, "recordSHA256": NativeAttachmentDraftStore.ownedAvailabilityDiscardFingerprint(record),
            "operations": Self.availabilityDiscardOperations(record, candidateIDs: Set(candidates.map(\.requestId))).map(\.object)] as [String: Any])
        return PendingCommand(version: 2, method: Self.ownedDiscardMethod, argumentsJSON: try Self.ownedJSON([wrapper]))
    }

    func discardAttachmentDraftV3(requestJSON: String, cancellation: NativeAttachmentCancellation) throws -> String {
        guard providerCopy?.receipt != nil || providerCopy == nil else { throw HostFailure("Attachment provider is loading") }
        dispatchPrecondition(condition: .onQueue(queue))
        if let selected = try NativeAttachmentDraftStore(databaseURL: databaseURL).readVersioned(), case .availability = selected.record {
            return try discardAvailabilityDraft(requestJSON: requestJSON, cancellation: cancellation)
        }
        do {
            guard started, !closed, !recoveryActivationPending, pending == nil, lockFD >= 0,
                  try ownedJournalIsAbsent(), let runtime = context, let jobs = attachmentJobs,
                  var binding = try NativeAttachmentDraftStore(databaseURL: databaseURL).readVersioned(),
                  case .mixed(let record) = binding.record else { throw Self.ownedDiscardFailure }
            let store = NativeAttachmentDraftStore(databaseURL: databaseURL)
            var editorBinding = try mixedSaveFileBinding(editorDrafts.url, maximumBytes: 3_000_000)
            let generation = attachmentGeneration
            func requireDecisionOwner() throws {
                try cancellation.check()
                guard started, !closed, !recoveryActivationPending, pending == nil, lockFD >= 0,
                      context === runtime, attachmentGeneration == generation, attachmentJobs === jobs,
                      try ownedJournalIsAbsent(),
                      try mixedSaveFileBinding(editorDrafts.url, maximumBytes: 3_000_000) == editorBinding,
                      let actual = try mixedSaveFileBinding(store.url, maximumBytes: Self.ownedSaveMaximumBytes),
                      actual.bytes == binding.bytes, UInt64(actual.identity.device) == binding.device,
                      UInt64(actual.identity.inode) == binding.inode else { throw Self.ownedDiscardFailure }
            }
            let coordinator = try NativeAttachmentDraftCoordinator(databaseURL: databaseURL, jobs: jobs,
                requireOwner: { try requireDecisionOwner() }) { [unowned self] method, args in try self.invoke(method, arguments: args) }
            #if DEBUG
            coordinator.hooks = attachmentDraftHooks
            #endif
            coordinator.drainOwnedSaveJobs(); try requireDecisionOwner()
            let decision = try coordinator.prepareMixedDiscardDecision(requestJSON, record: record)
            if let current = try editorDrafts.read() {
                guard current.attempt == nil, Self.ownedEqual(current.snapshot, record.session.checkpoint) else { throw Self.ownedDiscardFailure }
            } else { guard record.discard != nil else { throw Self.ownedDiscardFailure } }
            _ = try coordinator.prepareMixedDiscardCandidates(record, binding: binding, cancellation: cancellation)
            try requireDecisionOwner()
            // Fresh capacity is reserved before either private intent or editor
            // detachment. Retained decisions reserve only their actual owed form.
            if record.discard == nil { try store.preflightMixed(decision.decided) }
            try store.preflightMixed(decision.detached)
            try preflightOwnedDiscard(ownedMixedDiscardCommand(decision.detached))
            if record.discard?.phase != .detached {
                #if DEBUG
                try attachmentDraftHooks?.boundary?(.beforeDiscardDecision)
                #endif
                try requireDecisionOwner()
                binding = try store.writeMixedAcknowledged(decision.decided)
                #if DEBUG
                try attachmentDraftHooks?.boundary?(.afterDiscardDecision)
                #endif
                try requireDecisionOwner()
            }
            if record.discard?.phase != .detached {
                #if DEBUG
                try attachmentDraftHooks?.boundary?(.beforeDetach)
                #endif
                try requireDecisionOwner()
                if editorBinding == nil {
                    // Only a retained decision permits missing; acknowledge its
                    // parent durability again before promoting to detached.
                    try DurableFile.remove(editorDrafts.url)
                } else { try editorDrafts.discardMatching(expected: decision.decided.session.checkpoint) }
                guard try mixedSaveFileBinding(editorDrafts.url, maximumBytes: 3_000_000) == nil else { throw Self.ownedDiscardFailure }
                editorBinding = nil
                #if DEBUG
                try attachmentDraftHooks?.boundary?(.afterDetach)
                #endif
                try requireDecisionOwner()
            } else { guard editorBinding == nil else { throw Self.ownedDiscardFailure } }
            binding = try store.writeMixedAcknowledged(decision.detached)
            try requireDecisionOwner()
            return decision.replyJSON
        } catch { throw Self.ownedDiscardFailure }
    }

    private func discardAvailabilityDraft(requestJSON: String, cancellation: NativeAttachmentCancellation) throws -> String {
        do {
            guard started, !closed, !recoveryActivationPending, pending == nil, lockFD >= 0,
                  try ownedJournalIsAbsent(), let runtime = context, let jobs = attachmentJobs,
                  var binding = try NativeAttachmentDraftStore(databaseURL: databaseURL).readVersioned(),
                  case .availability(let record) = binding.record else { throw Self.ownedDiscardFailure }
            let store = NativeAttachmentDraftStore(databaseURL: databaseURL)
            var editorBinding = try mixedSaveFileBinding(editorDrafts.url, maximumBytes: 3_000_000)
            let generation = attachmentGeneration
            func requireDecisionOwner() throws {
                try cancellation.check()
                guard started, !closed, !recoveryActivationPending, pending == nil, lockFD >= 0,
                      context === runtime, attachmentGeneration == generation, attachmentJobs === jobs, try ownedJournalIsAbsent(),
                      try mixedSaveFileBinding(editorDrafts.url, maximumBytes: 3_000_000) == editorBinding,
                      let actual = try mixedSaveFileBinding(store.url, maximumBytes: Self.ownedSaveMaximumBytes),
                      actual.bytes == binding.bytes, UInt64(actual.identity.device) == binding.device,
                      UInt64(actual.identity.inode) == binding.inode else { throw Self.ownedDiscardFailure }
            }
            let coordinator = try NativeAttachmentDraftCoordinator(databaseURL: databaseURL, jobs: jobs, requireOwner: requireDecisionOwner) {
                [unowned self] method, args in try self.invoke(method, arguments: args)
            }
            #if DEBUG
            coordinator.hooks = attachmentDraftHooks
            #endif
            coordinator.drainOwnedSaveJobs(); try requireDecisionOwner()
            let decision = try coordinator.prepareAvailabilityDiscardDecision(requestJSON, record: record)
            if let current = try editorDrafts.read() {
                guard current.attempt == nil, Self.ownedEqual(current.snapshot, record.session.checkpoint) else { throw Self.ownedDiscardFailure }
            } else { guard record.discard != nil else { throw Self.ownedDiscardFailure } }
            let candidates = try coordinator.prepareAvailabilityDiscardCandidates(record,
                binding: .init(record: record, bytes: binding.bytes, device: binding.device, inode: binding.inode), cancellation: cancellation)
            try requireDecisionOwner()
            if record.discard == nil { try store.preflightAvailability(decision.decided) }
            try store.preflightAvailability(decision.detached)
            try preflightOwnedDiscard(ownedAvailabilityDiscardCommand(decision.detached, candidates: candidates))
            if record.discard?.phase != .detached {
                #if DEBUG
                try attachmentDraftHooks?.boundary?(.beforeDiscardDecision)
                #endif
                try requireDecisionOwner()
                let next = try store.writeAvailabilityAcknowledged(decision.decided)
                binding = .init(record: .availability(next.record), bytes: next.bytes, device: next.device, inode: next.inode)
                #if DEBUG
                try attachmentDraftHooks?.boundary?(.afterDiscardDecision)
                #endif
                try requireDecisionOwner()
                #if DEBUG
                try attachmentDraftHooks?.boundary?(.beforeDetach)
                #endif
                try requireDecisionOwner()
                if editorBinding == nil { try DurableFile.remove(editorDrafts.url) }
                else { try editorDrafts.discardMatching(expected: decision.decided.session.checkpoint) }
                guard try mixedSaveFileBinding(editorDrafts.url, maximumBytes: 3_000_000) == nil else { throw Self.ownedDiscardFailure }
                editorBinding = nil
                #if DEBUG
                try attachmentDraftHooks?.boundary?(.afterDetach)
                #endif
                try requireDecisionOwner()
            } else { guard editorBinding == nil else { throw Self.ownedDiscardFailure } }
            let next = try store.writeAvailabilityAcknowledged(decision.detached)
            binding = .init(record: .availability(next.record), bytes: next.bytes, device: next.device, inode: next.inode)
            try requireDecisionOwner()
            return decision.replyJSON
        } catch { throw Self.ownedDiscardFailure }
    }
    private func availabilityDiscardPlan(_ command: PendingCommand, turn: OwnedDiscardTurn,
                                         cancellation: NativeAttachmentCancellation, unjournaled: Bool = false) throws -> [NativeAttachmentDraftStore.AvailabilityOperation] {
        guard let binding = turn.mixedBinding, case .availability(let record) = binding.record,
              let captured = turn.mixedValidated, captured.version == 7 else { throw Self.ownedDiscardFailure }
        let coordinator: NativeAttachmentDraftCoordinator
        if unjournaled { coordinator = try mixedDiscardCoordinator(command, turn: turn, cancellation: cancellation, unjournaled: true) }
        else {
            guard let jobs = turn.jobs else { throw Self.ownedDiscardFailure }
            coordinator = try NativeAttachmentDraftCoordinator(databaseURL: databaseURL, jobs: jobs, requireOwner: { [unowned self] in
                _ = try self.requireMixedDiscardEvidence(command, turn: turn, cancellation: cancellation)
            }) { [unowned self] method, args in try self.invoke(method, arguments: args) }
            #if DEBUG
            coordinator.hooks = attachmentDraftHooks
            #endif
        }
        let plan = try coordinator.prepareAvailabilityDiscardCandidates(record,
            binding: .init(record: record, bytes: binding.bytes, device: binding.device, inode: binding.inode), cancellation: cancellation)
        guard captured.mixedOperations == Self.availabilityDiscardOperations(record, candidateIDs: Set(plan.map(\.requestId))) else { throw Self.ownedDiscardFailure }
        return plan
    }
    private func finishAvailabilityDraftDiscard(expectedSession: String, requestId: String,
                                                cancellation: NativeAttachmentCancellation) throws -> String {
        do {
            guard started, !closed, !recoveryActivationPending, pending == nil,
                  Self.ownedDiscardUUID(expectedSession) != nil, Self.ownedDiscardUUID(requestId) != nil,
                  let binding = try NativeAttachmentDraftStore(databaseURL: databaseURL).readAvailabilitySnapshot(),
                  Self.ownedEqual(binding.record.session.sessionID, expectedSession),
                  binding.record.discard.map({ Self.ownedEqual($0.requestId, requestId) }) == true,
                  let runtime = context, let jobs = attachmentJobs else { throw Self.ownedDiscardFailure }
            let record = binding.record
            // Construct the journal only after the selected pure planner has
            // bound exact candidate membership; no physical work precedes it.
            let generation = attachmentGeneration
            func requireInitial() throws {
                try cancellation.check()
                guard started, !closed, !recoveryActivationPending, pending == nil, lockFD >= 0,
                      context === runtime, attachmentJobs === jobs, attachmentGeneration == generation,
                      try ownedJournalIsAbsent(), try mixedSaveFileBinding(editorDrafts.url, maximumBytes: 3_000_000) == nil,
                      let actual = try NativeAttachmentDraftStore(databaseURL: databaseURL).readAvailabilitySnapshot(), binding.matches(actual) else { throw Self.ownedDiscardFailure }
            }
            let initial = try NativeAttachmentDraftCoordinator(databaseURL: databaseURL, jobs: jobs, requireOwner: requireInitial) {
                [unowned self] method, args in try self.invoke(method, arguments: args)
            }
            #if DEBUG
            initial.hooks = attachmentDraftHooks
            #endif
            initial.drainOwnedSaveJobs(); try requireInitial()
            let plan = try initial.prepareAvailabilityDiscardCandidates(record, binding: binding, cancellation: cancellation)
            var command = try ownedAvailabilityDiscardCommand(record, candidates: plan)
            var turn = try ownedDiscardTurn(command)
            var coordinator = try mixedDiscardCoordinator(command, turn: turn, cancellation: cancellation, unjournaled: true)
            turn.availabilityPlan = plan
            try preflightOwnedDiscard(command)
            if let op = record.operations.last, op.phase == .stageFilled, case .owned = op.resource {
                let adapter = try NativeAttachmentDraftCoordinator.availabilityOwnedOperation(op)
                #if DEBUG
                try attachmentDraftHooks?.boundary?(.beforeDiscardFilledObservation)
                #endif
                try requireUnjournaledDiscard(command, turn: turn, cancellation: cancellation)
                let observed: Bool
                do { try coordinator.observeOwnedDiscardFilledStage(adapter, cancellation: cancellation); observed = true }
                catch { try requireUnjournaledDiscard(command, turn: turn, cancellation: cancellation); observed = false }
                #if DEBUG
                try attachmentDraftHooks?.boundary?(.afterDiscardFilledObservation)
                #endif
                try requireUnjournaledDiscard(command, turn: turn, cancellation: cancellation)
                if !observed {
                    #if DEBUG
                    try attachmentDraftHooks?.boundary?(.beforeDiscardPublicationReproof)
                    #endif
                    let proof = try coordinator.reproveOwnedDiscardPublication(adapter, cancellation: cancellation)
                    #if DEBUG
                    try attachmentDraftHooks?.boundary?(.afterDiscardPublicationReproof)
                    #endif
                    try requireUnjournaledDiscard(command, turn: turn, cancellation: cancellation)
                    let promoted = try coordinator.promotedAvailabilityDiscard(record, proof: proof)
                    let store = NativeAttachmentDraftStore(databaseURL: databaseURL)
                    try store.preflightAvailability(promoted)
                    let nextPlan = promoted.operations.filter { op in plan.contains { Self.ownedEqual($0.requestId, op.requestId) } }
                    let nextCommand = try ownedAvailabilityDiscardCommand(promoted, candidates: nextPlan)
                    try preflightOwnedDiscard(nextCommand)
                    #if DEBUG
                    try attachmentDraftHooks?.boundary?(.beforeDiscardPublicationPromotion)
                    #endif
                    try requireUnjournaledDiscard(command, turn: turn, cancellation: cancellation)
                    let next = try store.writeAvailabilityAcknowledged(promoted)
                    try requireUnjournaledDiscardOwner(turn, cancellation: cancellation)
                    command = nextCommand; turn = try ownedDiscardTurn(command)
                    guard let rebound = turn.mixedBinding, rebound.bytes == next.bytes, rebound.device == next.device, rebound.inode == next.inode else { throw Self.ownedDiscardFailure }
                    turn.availabilityPlan = try availabilityDiscardPlan(command, turn: turn, cancellation: cancellation, unjournaled: true)
                    coordinator = try mixedDiscardCoordinator(command, turn: turn, cancellation: cancellation, unjournaled: true)
                    #if DEBUG
                    try attachmentDraftHooks?.boundary?(.afterDiscardPublicationPromotion)
                    #endif
                    try requireUnjournaledDiscard(command, turn: turn, cancellation: cancellation)
                }
            }
            #if DEBUG
            try attachmentDraftHooks?.boundary?(.beforeDiscardFinishJournal)
            #endif
            try requireUnjournaledDiscard(command, turn: turn, cancellation: cancellation)
            pending = command; try persistMixedDiscard(command, turn: turn, cancellation: cancellation)
            #if DEBUG
            try attachmentDraftHooks?.boundary?(.afterDiscardFinishJournal)
            #endif
            _ = try requireMixedDiscardAuthority(command, turn: turn, cancellation: cancellation)
            return try executeAvailabilityDiscard(command, turn: turn, cancellation: cancellation).value()
        } catch { throw Self.ownedDiscardFailure }
    }

    private func requireMixedDiscardEvidence(_ command: PendingCommand, turn: OwnedDiscardTurn,
                                             cancellation: NativeAttachmentCancellation) throws -> Bool {
        dispatchPrecondition(condition: .onQueue(queue))
        try cancellation.check()
        guard started, !closed, lockFD >= 0, context === turn.runtime, attachmentGeneration == turn.generation,
              let jobs = turn.jobs, attachmentJobs === jobs, let current = pending,
              try ownedEncoded(current) == ownedEncoded(command),
              try mixedSaveFileBinding(journalURL, maximumBytes: Self.ownedSaveMaximumBytes) == turn.mixedJournal,
              try mixedSaveFileBinding(editorDrafts.url, maximumBytes: 3_000_000) == nil else { throw Self.ownedDiscardFailure }
        if let actual = try mixedSaveFileBinding(NativeAttachmentDraftStore(databaseURL: databaseURL).url, maximumBytes: Self.ownedSaveMaximumBytes) {
            guard let binding = turn.mixedBinding, actual.bytes == binding.bytes,
                  UInt64(actual.identity.device) == binding.device, UInt64(actual.identity.inode) == binding.inode else { throw Self.ownedDiscardFailure }
            return true
        }
        guard case .success = turn.mixedAcknowledged?.terminal else { throw Self.ownedDiscardFailure }
        return false
    }
    private func requireMixedDiscardAuthority(_ command: PendingCommand, turn: OwnedDiscardTurn,
                                              cancellation: NativeAttachmentCancellation, promotion: Bool = false,
                                              sidecarAbsent: Bool = false) throws -> OwnedDiscardJournal {
        guard let captured = turn.mixedValidated, let acknowledged = turn.mixedAcknowledged,
              turn.mixedJournal != nil else { throw Self.ownedDiscardFailure }
        var before = acknowledged, after = command; before.terminal = nil; after.terminal = nil
        guard try ownedEncoded(before) == ownedEncoded(after) else { throw Self.ownedDiscardFailure }
        if promotion && acknowledged.terminal == nil {
            guard case .success(let value) = command.terminal else { throw Self.ownedDiscardFailure }
            try validateMixedDiscardResult(value, captured: captured)
        } else { guard try ownedEncoded(acknowledged) == ownedEncoded(command) else { throw Self.ownedDiscardFailure } }
        let present = try requireMixedDiscardEvidence(command, turn: turn, cancellation: cancellation)
        if sidecarAbsent { guard !present else { throw Self.ownedDiscardFailure } }
        return captured
    }
    private func persistMixedDiscard(_ command: PendingCommand, turn: OwnedDiscardTurn,
                                     cancellation: NativeAttachmentCancellation) throws {
        _ = try requireMixedDiscardEvidence(command, turn: turn, cancellation: cancellation)
        try persist(command, mixedGuard: { [unowned self] in
            _ = try self.requireMixedDiscardEvidence(command, turn: turn, cancellation: cancellation)
        })
        guard let written = try mixedSaveFileBinding(journalURL, maximumBytes: Self.ownedSaveMaximumBytes),
              written.bytes == (try ownedEncoded(command)) else { throw Self.ownedDiscardFailure }
        turn.mixedJournal = written; turn.mixedAcknowledged = command
        _ = try requireMixedDiscardAuthority(command, turn: turn, cancellation: cancellation)
    }
    private func mixedDiscardCoordinator(_ command: PendingCommand, turn: OwnedDiscardTurn,
                                          cancellation: NativeAttachmentCancellation,
                                          unjournaled: Bool = false) throws -> NativeAttachmentDraftCoordinator {
        guard let jobs = turn.jobs else { throw Self.ownedDiscardFailure }
        let coordinator = try NativeAttachmentDraftCoordinator(databaseURL: databaseURL, jobs: jobs, requireOwner: { [unowned self] in
            if unjournaled { try self.requireUnjournaledDiscard(command, turn: turn, cancellation: cancellation) }
            else { _ = try self.requireMixedDiscardAuthority(command, turn: turn, cancellation: cancellation) }
        }) { [unowned self] method, args in try self.invoke(method, arguments: args) }
        #if DEBUG
        coordinator.hooks = attachmentDraftHooks
        #endif
        return coordinator
    }

    func finishAttachmentDraftDiscardV3(expectedSession: String, requestId: String,
                                        cancellation: NativeAttachmentCancellation) throws -> String {
        dispatchPrecondition(condition: .onQueue(queue))
        if let selected = try NativeAttachmentDraftStore(databaseURL: databaseURL).readVersioned(), case .availability = selected.record {
            return try finishAvailabilityDraftDiscard(expectedSession: expectedSession, requestId: requestId, cancellation: cancellation)
        }
        do {
            guard started, !closed, !recoveryActivationPending, pending == nil,
                  Self.ownedDiscardUUID(expectedSession) != nil, Self.ownedDiscardUUID(requestId) != nil,
                  let binding = try NativeAttachmentDraftStore(databaseURL: databaseURL).readVersioned(),
                  case .mixed(let record) = binding.record, Self.ownedEqual(record.session.sessionID, expectedSession),
                  record.discard.map({ Self.ownedEqual($0.requestId, requestId) }) == true else { throw Self.ownedDiscardFailure }
            var command = try ownedMixedDiscardCommand(record)
            var turn = try ownedDiscardTurn(command)
            var coordinator = try mixedDiscardCoordinator(command, turn: turn, cancellation: cancellation, unjournaled: true)
            coordinator.drainOwnedSaveJobs(); try requireUnjournaledDiscard(command, turn: turn, cancellation: cancellation)
            turn.mixedPlan = try coordinator.prepareMixedDiscardCandidates(record, binding: binding, cancellation: cancellation)
            try preflightOwnedDiscard(command)
            if let last = record.operations.last, case .add(let op) = last, op.phase == .stageFilled {
                #if DEBUG
                try attachmentDraftHooks?.boundary?(.beforeDiscardFilledObservation)
                #endif
                try requireUnjournaledDiscard(command, turn: turn, cancellation: cancellation)
                let observed: Bool
                do { try coordinator.observeOwnedDiscardFilledStage(op, cancellation: cancellation); observed = true }
                catch { try requireUnjournaledDiscard(command, turn: turn, cancellation: cancellation); observed = false }
                #if DEBUG
                try attachmentDraftHooks?.boundary?(.afterDiscardFilledObservation)
                #endif
                try requireUnjournaledDiscard(command, turn: turn, cancellation: cancellation)
                if !observed {
                    #if DEBUG
                    try attachmentDraftHooks?.boundary?(.beforeDiscardPublicationReproof)
                    #endif
                    try requireUnjournaledDiscard(command, turn: turn, cancellation: cancellation)
                    let proof = try coordinator.reproveOwnedDiscardPublication(op, cancellation: cancellation)
                    #if DEBUG
                    try attachmentDraftHooks?.boundary?(.afterDiscardPublicationReproof)
                    #endif
                    try requireUnjournaledDiscard(command, turn: turn, cancellation: cancellation)
                    let promoted = try coordinator.promotedMixedDiscard(record, proof: proof)
                    let store = NativeAttachmentDraftStore(databaseURL: databaseURL)
                    try store.preflightMixed(promoted)
                    let promotedCommand = try ownedMixedDiscardCommand(promoted)
                    try preflightOwnedDiscard(promotedCommand)
                    #if DEBUG
                    try attachmentDraftHooks?.boundary?(.beforeDiscardPublicationPromotion)
                    #endif
                    try requireUnjournaledDiscard(command, turn: turn, cancellation: cancellation)
                    let next = try store.writeMixedAcknowledged(promoted)
                    try requireUnjournaledDiscardOwner(turn, cancellation: cancellation)
                    command = promotedCommand
                    turn = try ownedDiscardTurn(command)
                    guard let rebound = turn.mixedBinding, rebound.matches(next) else { throw Self.ownedDiscardFailure }
                    turn.mixedPlan = try NativeAttachmentDraftCoordinator.mixedDiscardAdds(promoted)
                    coordinator = try mixedDiscardCoordinator(command, turn: turn, cancellation: cancellation, unjournaled: true)
                    #if DEBUG
                    try attachmentDraftHooks?.boundary?(.afterDiscardPublicationPromotion)
                    #endif
                    try requireUnjournaledDiscard(command, turn: turn, cancellation: cancellation)
                }
            }
            #if DEBUG
            try attachmentDraftHooks?.boundary?(.beforeDiscardFinishJournal)
            #endif
            try requireUnjournaledDiscard(command, turn: turn, cancellation: cancellation)
            pending = command
            try persistMixedDiscard(command, turn: turn, cancellation: cancellation)
            #if DEBUG
            try attachmentDraftHooks?.boundary?(.afterDiscardFinishJournal)
            #endif
            _ = try requireMixedDiscardAuthority(command, turn: turn, cancellation: cancellation)
            return try executeMixedDiscard(command, turn: turn, cancellation: cancellation).value()
        } catch { throw Self.ownedDiscardFailure }
    }

    func finishAttachmentDraftDiscard(expectedSession: String, requestId: String,
                                      cancellation: NativeAttachmentCancellation) throws -> String {
        dispatchPrecondition(condition: .onQueue(queue))
        do {
            guard started, !closed, !recoveryActivationPending, pending == nil,
                  Self.ownedDiscardUUID(expectedSession) != nil, Self.ownedDiscardUUID(requestId) != nil,
                  var record = try NativeAttachmentDraftStore(databaseURL: databaseURL).read(),
                  Self.ownedEqual(record.session.sessionID, expectedSession),
                  record.discard.map({ Self.ownedEqual($0.requestId, requestId) }) == true else { throw Self.ownedDiscardFailure }
            let version = try NativeAttachmentDraftCoordinator.ownedDiscardVersion(record)
            var command = try ownedDiscardCommand(record)
            var turn = try ownedDiscardTurn(command)
            let coordinator = try ownedSaveCoordinatorForWork()
            if version == 3 || version == 4 {
                // Both historical formats must drain before intent abandonment
                // or fresh filled-stage classification.
                // The fresh strict record and inode must still be this decision.
                coordinator.drainOwnedSaveJobs()
                try requireUnjournaledDiscard(command, turn: turn, cancellation: cancellation)
            }
            _ = try coordinator.prepareOwnedDiscardCandidates(record)
            try preflightOwnedDiscard(command)
            if version == 4 {
                guard let op = record.operations.last else { throw Self.ownedDiscardFailure }
                #if DEBUG
                try attachmentDraftHooks?.boundary?(.beforeDiscardFilledObservation)
                #endif
                try requireUnjournaledDiscard(command, turn: turn, cancellation: cancellation)
                let observed: Bool
                do { try coordinator.observeOwnedDiscardFilledStage(op, cancellation: cancellation); observed = true }
                catch {
                    // An observer error grants no permission. Only a separate
                    // positive publication proof can select the other branch.
                    try requireUnjournaledDiscard(command, turn: turn, cancellation: cancellation)
                    observed = false
                }
                #if DEBUG
                try attachmentDraftHooks?.boundary?(.afterDiscardFilledObservation)
                #endif
                try requireUnjournaledDiscard(command, turn: turn, cancellation: cancellation)
                if !observed {
                    #if DEBUG
                    try attachmentDraftHooks?.boundary?(.beforeDiscardPublicationReproof)
                    #endif
                    try requireUnjournaledDiscard(command, turn: turn, cancellation: cancellation)
                    let proof = try coordinator.reproveOwnedDiscardPublication(op, cancellation: cancellation)
                    #if DEBUG
                    try attachmentDraftHooks?.boundary?(.afterDiscardPublicationReproof)
                    #endif
                    try requireUnjournaledDiscard(command, turn: turn, cancellation: cancellation)
                    #if DEBUG
                    try attachmentDraftHooks?.boundary?(.beforeDiscardPublicationPromotion)
                    #endif
                    try requireUnjournaledDiscard(command, turn: turn, cancellation: cancellation)
                    let promoted = try coordinator.promoteOwnedDiscardPublication(record, proof: proof)
                    try requireUnjournaledDiscardOwner(turn, cancellation: cancellation)
                    guard let actual = try NativeAttachmentDraftStore(databaseURL: databaseURL).read(),
                          Self.ownedEqual(try NativeAttachmentDraftStore.ownedDiscardFingerprint(actual),
                                          try NativeAttachmentDraftStore.ownedDiscardFingerprint(promoted)) else { throw Self.ownedDiscardFailure }
                    record = actual
                    command = try ownedDiscardCommand(record)
                    turn = try ownedDiscardTurn(command)
                    try requireUnjournaledDiscard(command, turn: turn, cancellation: cancellation)
                    NSLog("Native iOS attachment publication recovered releaseCheck=v1.3.5/ios-discard-publication-reproof outcome=recorded")
                    #if DEBUG
                    try attachmentDraftHooks?.boundary?(.afterDiscardPublicationPromotion)
                    #endif
                    try requireUnjournaledDiscard(command, turn: turn, cancellation: cancellation)
                    try preflightOwnedDiscard(command)
                }
            }
            try cancellation.check()
            #if DEBUG
            try attachmentDraftHooks?.boundary?(.beforeDiscardFinishJournal)
            #endif
            try requireUnjournaledDiscard(command, turn: turn, cancellation: cancellation)
            pending = command
            // A visible earlier promotion is not an acknowledgment by itself.
            // This sibling journal's successful parent fsync orders that rename
            // before cleanup; an uncertain journal write starts no retirement.
            try persist(command)
            turn.journalIdentity = try ownedDiscardIdentity(journalURL)
            #if DEBUG
            try attachmentDraftHooks?.boundary?(.afterDiscardFinishJournal)
            #endif
            _ = try requireOwnedDiscardAuthority(command, turn: turn, cancellation: cancellation)
            return try executeOwnedDiscard(command, cancellation: cancellation, turn: turn).value()
        } catch { throw Self.ownedDiscardFailure }
    }

    /// The native callbacks complete before JSC returns and drains microtasks.
    /// No invoke, timer pumping, diagnostic or JSC value enters the file queue.
    private func ownedDiscardTargetHandoff(_ command: PendingCommand, turn: OwnedDiscardTurn,
                                           op: NativeAttachmentDraftStore.Operation,
                                           coordinator: NativeAttachmentDraftCoordinator,
                                           cancellation: NativeAttachmentCancellation) throws -> String {
        _ = try requireOwnedDiscardAuthority(command, turn: turn, cancellation: cancellation)
        guard let host = turn.runtime.objectForKeyedSubscript("MindwtrHost"), !invoking else { throw Self.ownedDiscardFailure }
        let lease = OwnedDiscardCallbackLease()
        lease.work = { [weak self] referenced in
            guard let self else { throw Self.ownedDiscardFailure }
            _ = try self.requireOwnedDiscardAuthority(command, turn: turn, cancellation: cancellation)
            let outcome = referenced ? "referenced" : try coordinator.retireOwnedDiscardTarget(op, cancellation: cancellation)
            _ = try self.requireOwnedDiscardAuthority(command, turn: turn, cancellation: cancellation)
            return outcome
        }
        let keep: @convention(block) () -> String = { [weak lease] in
            lease?.enter(referenced: true) ?? "!MindwtrNativeError:Attachment Discard callback is unavailable"
        }
        let retire: @convention(block) () -> String = { [weak lease] in
            lease?.enter(referenced: false) ?? "!MindwtrNativeError:Attachment Discard callback is unavailable"
        }
        invoking = true
        defer { lease.invalidate(); invoking = false; scheduleAttachmentIdle(immediate: true) }
        turn.runtime.exception = nil
        let input = try Self.ownedJSON(["version": 1, "requestId": op.requestId, "targetURI": op.targetURI])
        guard let keepValue = JSValue(object: keep, in: turn.runtime),
              let retireValue = JSValue(object: retire, in: turn.runtime),
              turn.runtime.exception == nil else { throw Self.ownedDiscardFailure }
        let returned = host.invokeMethod("attachmentDraftDiscardRetire", withArguments: [input, keepValue, retireValue])
        // Never expose arbitrary JS exception content. A callback/outer failure
        // keeps the journal even if an unlink already completed.
        let threw = turn.runtime.exception != nil
        turn.runtime.exception = nil
        guard !threw, lease.consumed, !lease.failed, let outcome = lease.outcome,
              let returned, returned.isString, let text = returned.toString(), text.utf8.count <= 1024,
              let value = try NativeJSON.jsonObject(with: Data(text.utf8)) as? [String: Any],
              Set(value.keys) == Set(["outcome"]), value["outcome"] as? String == outcome else { throw Self.ownedDiscardFailure }
        _ = try requireOwnedDiscardAuthority(command, turn: turn, cancellation: cancellation)
        return outcome
    }

    private func executeOwnedDiscard(_ command: PendingCommand, cancellation: NativeAttachmentCancellation,
                                     turn supplied: OwnedDiscardTurn? = nil) throws -> TerminalResult {
        if try ownedDiscardJournal(command, checkingNative: false).version >= 5 {
            let turn = try supplied ?? ownedDiscardTurn(command)
            if turn.mixedValidated?.version == 7, turn.mixedBinding != nil {
                turn.availabilityPlan = try availabilityDiscardPlan(command, turn: turn, cancellation: cancellation)
            }
            if supplied == nil { try persistMixedDiscard(command, turn: turn, cancellation: cancellation) }
            return try executeMixedDiscard(command, turn: turn, cancellation: cancellation)
        }
        do {
            let turn = try supplied ?? ownedDiscardTurn(command)
            // Warm unknown writes are owed; identity guards forbid overwriting
            // foreign evidence. Historical terminals never start file jobs.
            if supplied == nil {
                try persist(command)
                turn.journalIdentity = try ownedDiscardIdentity(journalURL)
            }
            if command.terminal != nil { return try finishOwnedDiscardTerminal(command, turn: turn, cancellation: cancellation) }
            let captured = try requireOwnedDiscardAuthority(command, turn: turn, cancellation: cancellation)
            guard let record = captured.record else { throw Self.ownedDiscardFailure }
            let coordinator = try ownedSaveCoordinatorForWork()
            let operations = try coordinator.prepareOwnedDiscardCandidates(record)
            _ = try requireOwnedDiscardAuthority(command, turn: turn, cancellation: cancellation)
            var outcomes: [[String: String]] = []
            for (index, op) in operations.enumerated() {
                _ = try requireOwnedDiscardAuthority(command, turn: turn, cancellation: cancellation)
                let target: String
                if captured.version >= 2 && index == operations.count - 1 {
                    // No public content/proof/reference query or mutation. A
                    // recorded stage job retains confined path validation;
                    // the unclaimed intent below does not submit that job.
                    target = "untouched"
                } else {
                    #if DEBUG
                    try attachmentDraftHooks?.boundary?(.beforeDiscardTarget(index))
                    #endif
                    _ = try requireOwnedDiscardAuthority(command, turn: turn, cancellation: cancellation)
                    target = try ownedDiscardTargetHandoff(command, turn: turn, op: op, coordinator: coordinator, cancellation: cancellation)
                    #if DEBUG
                    try attachmentDraftHooks?.boundary?(.afterDiscardTarget(index))
                    #endif
                    _ = try requireOwnedDiscardAuthority(command, turn: turn, cancellation: cancellation)
                }
                let stage: String
                if captured.version == 3 && index == operations.count - 1 {
                    // No recorded ownership: do not inspect, adopt or sweep even
                    // an apparently empty same-named private namespace.
                    stage = "unclaimed"
                } else {
                    #if DEBUG
                    try attachmentDraftHooks?.boundary?(.beforeDiscardStage(index))
                    #endif
                    _ = try requireOwnedDiscardAuthority(command, turn: turn, cancellation: cancellation)
                    stage = try coordinator.retireOwnedDiscardStage(op, cancellation: cancellation)
                    #if DEBUG
                    try attachmentDraftHooks?.boundary?(.afterDiscardStage(index))
                    #endif
                }
                _ = try requireOwnedDiscardAuthority(command, turn: turn, cancellation: cancellation)
                outcomes.append(["requestId": op.requestId, "target": target, "stage": stage])
            }
            coordinator.drainOwnedSaveJobs()
            var finished = command
            finished.terminal = .success(try ownedDiscardResult(captured, operations: outcomes))
            pending = finished
            return try finishOwnedDiscardTerminal(finished, turn: turn, cancellation: cancellation)
        } catch { throw Self.ownedDiscardFailure }
    }

    private func executeMixedDiscard(_ command: PendingCommand, turn: OwnedDiscardTurn,
                                     cancellation: NativeAttachmentCancellation) throws -> TerminalResult {
        if turn.mixedValidated?.version == 7 { return try executeAvailabilityDiscard(command, turn: turn, cancellation: cancellation) }
        do {
            if command.terminal != nil { return try finishMixedDiscardTerminal(command, turn: turn, cancellation: cancellation) }
            let captured = try requireMixedDiscardAuthority(command, turn: turn, cancellation: cancellation)
            guard let binding = captured.mixedBinding, case .mixed(let record) = binding.record else { throw Self.ownedDiscardFailure }
            let coordinator = try mixedDiscardCoordinator(command, turn: turn, cancellation: cancellation)
            if turn.mixedPlan == nil {
                turn.mixedPlan = try coordinator.prepareMixedDiscardCandidates(record, binding: binding, cancellation: cancellation)
            }
            guard let plan = turn.mixedPlan else { throw Self.ownedDiscardFailure }
            var addIndex = 0, outcomes: [[String: String]] = []
            for (index, entry) in record.operations.enumerated() {
                _ = try requireMixedDiscardAuthority(command, turn: turn, cancellation: cancellation)
                guard case .add(let op) = entry else {
                    outcomes.append(["kind": "remove", "requestId": entry.requestId, "disposition": "metadataOnly"])
                    continue
                }
                guard addIndex < plan.count, plan[addIndex] == op else { throw Self.ownedDiscardFailure }
                addIndex += 1
                let target: String
                if [.intent, .stagePrepared, .stageFilled].contains(op.phase) { target = "untouched" }
                else {
                    #if DEBUG
                    try attachmentDraftHooks?.boundary?(.beforeDiscardTarget(index))
                    #endif
                    _ = try requireMixedDiscardAuthority(command, turn: turn, cancellation: cancellation)
                    target = try ownedDiscardTargetHandoff(command, turn: turn, op: op, coordinator: coordinator, cancellation: cancellation)
                    #if DEBUG
                    try attachmentDraftHooks?.boundary?(.afterDiscardTarget(index))
                    #endif
                    _ = try requireMixedDiscardAuthority(command, turn: turn, cancellation: cancellation)
                }
                let stage: String
                if op.phase == .intent { stage = "unclaimed" }
                else {
                    #if DEBUG
                    try attachmentDraftHooks?.boundary?(.beforeDiscardStage(index))
                    #endif
                    _ = try requireMixedDiscardAuthority(command, turn: turn, cancellation: cancellation)
                    stage = try coordinator.retireOwnedDiscardStage(op, cancellation: cancellation)
                    #if DEBUG
                    try attachmentDraftHooks?.boundary?(.afterDiscardStage(index))
                    #endif
                    _ = try requireMixedDiscardAuthority(command, turn: turn, cancellation: cancellation)
                }
                outcomes.append(["kind": "add", "requestId": op.requestId, "target": target, "stage": stage])
            }
            guard addIndex == plan.count else { throw Self.ownedDiscardFailure }
            coordinator.drainOwnedSaveJobs()
            var finished = command
            finished.terminal = .success(try ownedDiscardResult(captured, operations: outcomes))
            pending = finished
            return try finishMixedDiscardTerminal(finished, turn: turn, cancellation: cancellation)
        } catch { throw Self.ownedDiscardFailure }
    }
    private func availabilityDiscardTargetHandoff(_ command: PendingCommand, turn: OwnedDiscardTurn,
                                                  op: NativeAttachmentDraftStore.AvailabilityOperation,
                                                  coordinator: NativeAttachmentDraftCoordinator,
                                                  cancellation: NativeAttachmentCancellation) throws -> String {
        _ = try requireMixedDiscardAuthority(command, turn: turn, cancellation: cancellation)
        guard let target = op.targetURI, let host = turn.runtime.objectForKeyedSubscript("MindwtrHost"), !invoking else { throw Self.ownedDiscardFailure }
        let lease = OwnedDiscardCallbackLease()
        lease.work = { [weak self] referenced in
            guard let self else { throw Self.ownedDiscardFailure }
            _ = try self.requireMixedDiscardAuthority(command, turn: turn, cancellation: cancellation)
            let outcome: String
            if referenced { outcome = "referenced" }
            else if case .borrowed = op.resource { outcome = try coordinator.retireAvailabilityTarget(op, cancellation: cancellation) }
            else {
                outcome = try self.durableAttachmentReferenceRetirement(targetURI: target, cancellation: cancellation, retainDurableReference: true,
                    requireOwner: { _ = try self.requireMixedDiscardAuthority(command, turn: turn, cancellation: cancellation) },
                    retire: { try coordinator.retireAvailabilityTarget(op, cancellation: cancellation) })
            }
            _ = try self.requireMixedDiscardAuthority(command, turn: turn, cancellation: cancellation)
            return outcome
        }
        let keep: @convention(block) () -> String = { [weak lease] in lease?.enter(referenced: true) ?? "!MindwtrNativeError:Attachment Discard callback is unavailable" }
        let retire: @convention(block) () -> String = { [weak lease] in lease?.enter(referenced: false) ?? "!MindwtrNativeError:Attachment Discard callback is unavailable" }
        invoking = true
        defer { lease.invalidate(); invoking = false; scheduleAttachmentIdle(immediate: true) }
        turn.runtime.exception = nil
        let input = try Self.ownedJSON(["version": 2, "requestId": op.requestId, "targetURI": target])
        guard let keepValue = JSValue(object: keep, in: turn.runtime), let retireValue = JSValue(object: retire, in: turn.runtime),
              turn.runtime.exception == nil else { throw Self.ownedDiscardFailure }
        let returned = host.invokeMethod("attachmentDraftDiscardRetireV5", withArguments: [input, keepValue, retireValue])
        let threw = turn.runtime.exception != nil; turn.runtime.exception = nil
        guard !threw, lease.consumed, !lease.failed, let outcome = lease.outcome,
              let returned, returned.isString, let text = returned.toString(), text.utf8.count <= 1024,
              let value = try NativeJSON.jsonObject(with: Data(text.utf8)) as? [String: Any],
              Set(value.keys) == Set(["outcome"]), value["outcome"] as? String == outcome else { throw Self.ownedDiscardFailure }
        _ = try requireMixedDiscardAuthority(command, turn: turn, cancellation: cancellation)
        return outcome
    }
    private func executeAvailabilityDiscard(_ command: PendingCommand, turn: OwnedDiscardTurn,
                                            cancellation: NativeAttachmentCancellation) throws -> TerminalResult {
        do {
            if command.terminal != nil { return try finishMixedDiscardTerminal(command, turn: turn, cancellation: cancellation) }
            let captured = try requireMixedDiscardAuthority(command, turn: turn, cancellation: cancellation)
            guard let binding = captured.mixedBinding, case .availability(let record) = binding.record else { throw Self.ownedDiscardFailure }
            let coordinator = try mixedDiscardCoordinator(command, turn: turn, cancellation: cancellation)
            if turn.availabilityPlan == nil { turn.availabilityPlan = try availabilityDiscardPlan(command, turn: turn, cancellation: cancellation) }
            guard let plan = turn.availabilityPlan else { throw Self.ownedDiscardFailure }
            var outcomes: [[String: String]] = []
            for (index, op) in record.operations.enumerated() {
                _ = try requireMixedDiscardAuthority(command, turn: turn, cancellation: cancellation)
                let candidate = plan.contains { Self.ownedEqual($0.requestId, op.requestId) }
                let target: String
                if !candidate || (op.phase.rank < NativeAttachmentDraftStore.Phase.published.rank && { if case .owned = op.resource { return true }; return false }()) {
                    target = "untouched"
                } else {
                    #if DEBUG
                    try attachmentDraftHooks?.boundary?(.beforeDiscardTarget(index))
                    #endif
                    _ = try requireMixedDiscardAuthority(command, turn: turn, cancellation: cancellation)
                    target = try availabilityDiscardTargetHandoff(command, turn: turn, op: op, coordinator: coordinator, cancellation: cancellation)
                    #if DEBUG
                    try attachmentDraftHooks?.boundary?(.afterDiscardTarget(index))
                    #endif
                    _ = try requireMixedDiscardAuthority(command, turn: turn, cancellation: cancellation)
                }
                let stage: String
                if case .owned = op.resource, op.phase != .intent {
                    #if DEBUG
                    try attachmentDraftHooks?.boundary?(.beforeDiscardStage(index))
                    #endif
                    _ = try requireMixedDiscardAuthority(command, turn: turn, cancellation: cancellation)
                    stage = try coordinator.retireAvailabilityStage(op, cancellation: cancellation)
                    #if DEBUG
                    try attachmentDraftHooks?.boundary?(.afterDiscardStage(index))
                    #endif
                    _ = try requireMixedDiscardAuthority(command, turn: turn, cancellation: cancellation)
                } else { stage = "unclaimed" }
                outcomes.append(["kind": "availability", "requestId": op.requestId, "target": target, "stage": stage])
            }
            coordinator.drainOwnedSaveJobs()
            var finished = command; finished.terminal = .success(try ownedDiscardResult(captured, operations: outcomes)); pending = finished
            return try finishMixedDiscardTerminal(finished, turn: turn, cancellation: cancellation)
        } catch { throw Self.ownedDiscardFailure }
    }
    private func finishMixedDiscardTerminal(_ command: PendingCommand, turn: OwnedDiscardTurn,
                                            cancellation: NativeAttachmentCancellation) throws -> TerminalResult {
        guard let terminal = command.terminal, case .success = terminal else { throw Self.ownedDiscardFailure }
        _ = try requireMixedDiscardAuthority(command, turn: turn, cancellation: cancellation, promotion: true)
        #if DEBUG
        try attachmentDraftHooks?.boundary?(.beforeDiscardTerminal)
        #endif
        _ = try requireMixedDiscardAuthority(command, turn: turn, cancellation: cancellation, promotion: true)
        try persistMixedDiscard(command, turn: turn, cancellation: cancellation)
        #if DEBUG
        try attachmentDraftHooks?.boundary?(.afterDiscardTerminal)
        #endif
        let captured = try requireMixedDiscardAuthority(command, turn: turn, cancellation: cancellation)
        #if DEBUG
        try attachmentDraftHooks?.boundary?(.beforeDiscardRelease)
        #endif
        _ = try requireMixedDiscardAuthority(command, turn: turn, cancellation: cancellation)
        if captured.version == 7 { try NativeAttachmentDraftStore(databaseURL: databaseURL).releaseDiscardedAvailabilityMatching(fingerprint: captured.fingerprint) }
        else { try NativeAttachmentDraftStore(databaseURL: databaseURL).releaseDiscardedMixedMatching(fingerprint: captured.fingerprint) }
        #if DEBUG
        try attachmentDraftHooks?.boundary?(.afterDiscardRelease)
        #endif
        _ = try requireMixedDiscardAuthority(command, turn: turn, cancellation: cancellation, sidecarAbsent: true)
        #if DEBUG
        try attachmentDraftHooks?.boundary?(.beforeDiscardJournalClear)
        try faults?.journalRemove?()
        #endif
        _ = try requireMixedDiscardAuthority(command, turn: turn, cancellation: cancellation, sidecarAbsent: true)
        try DurableFile.remove(journalURL)
        #if DEBUG
        try attachmentDraftHooks?.boundary?(.afterDiscardJournalClear)
        #endif
        try cancellation.check()
        guard started, !closed, lockFD >= 0, attachmentGeneration == turn.generation, context === turn.runtime,
              let jobs = turn.jobs, attachmentJobs === jobs, let current = pending,
              try ownedEncoded(current) == ownedEncoded(command),
              try mixedSaveFileBinding(editorDrafts.url, maximumBytes: 3_000_000) == nil,
              try mixedSaveFileBinding(NativeAttachmentDraftStore(databaseURL: databaseURL).url, maximumBytes: Self.ownedSaveMaximumBytes) == nil,
              try mixedSaveFileBinding(journalURL, maximumBytes: Self.ownedSaveMaximumBytes) == nil else { throw Self.ownedDiscardFailure }
        pending = nil
        _ = try? invoke("attachmentDraftAcknowledged", arguments: [captured.version == 7 ? "availability-discard" : "discard-mixed", captured.version == 7 ? "settled" : "confirmed"])
        return terminal
    }

    private func finishOwnedDiscardTerminal(_ command: PendingCommand, turn: OwnedDiscardTurn,
                                            cancellation: NativeAttachmentCancellation) throws -> TerminalResult {
        guard let terminal = command.terminal, case .success = terminal else { throw Self.ownedDiscardFailure }
        _ = try requireOwnedDiscardAuthority(command, turn: turn, cancellation: cancellation, terminalPromotion: true)
        #if DEBUG
        try attachmentDraftHooks?.boundary?(.beforeDiscardTerminal)
        #endif
        _ = try requireOwnedDiscardAuthority(command, turn: turn, cancellation: cancellation, terminalPromotion: true)
        try persist(command)
        turn.journalIdentity = try ownedDiscardIdentity(journalURL)
        #if DEBUG
        try attachmentDraftHooks?.boundary?(.afterDiscardTerminal)
        #endif
        let captured = try requireOwnedDiscardAuthority(command, turn: turn, cancellation: cancellation)
        #if DEBUG
        try attachmentDraftHooks?.boundary?(.beforeDiscardRelease)
        #endif
        _ = try requireOwnedDiscardAuthority(command, turn: turn, cancellation: cancellation)
        try NativeAttachmentDraftStore(databaseURL: databaseURL).releaseDiscardedAddsMatching(fingerprint: captured.fingerprint)
        #if DEBUG
        try attachmentDraftHooks?.boundary?(.afterDiscardRelease)
        #endif
        _ = try requireOwnedDiscardAuthority(command, turn: turn, cancellation: cancellation, sidecarAbsent: true)
        #if DEBUG
        try attachmentDraftHooks?.boundary?(.beforeDiscardJournalClear)
        try faults?.journalRemove?()
        #endif
        _ = try requireOwnedDiscardAuthority(command, turn: turn, cancellation: cancellation, sidecarAbsent: true)
        try DurableFile.remove(journalURL)
        #if DEBUG
        try attachmentDraftHooks?.boundary?(.afterDiscardJournalClear)
        #endif
        guard started, !closed, attachmentGeneration == turn.generation, context === turn.runtime,
              let current = pending, try ownedEncoded(current) == ownedEncoded(command),
              try ownedDiscardJournal(command).record == nil, try ownedJournalIsAbsent() else { throw Self.ownedDiscardFailure }
        pending = nil
        _ = try? invoke("attachmentDraftAcknowledged", arguments: [captured.version == 3 ? "discard-unstarted" : "discard-finish", "confirmed"])
        return terminal
    }

    func saveAttachmentDraftAdds(saveRequestJSON: String, expectedSession: String, expectedGeneration: Int) throws -> String {
        dispatchPrecondition(condition: .onQueue(queue))
        guard started, !closed, !recoveryActivationPending, pending == nil else { throw Self.ownedSaveFailure }
        do {
            let prepared = try attachmentDraftCoordinator().prepareOwnedSave(saveRequestJSON,
                session: expectedSession, generation: expectedGeneration)
            let original = try Self.ownedJSON([saveRequestJSON])
            let attempt = EditorDraftAttempt(id: UUID().uuidString.lowercased(), sessionID: prepared.snapshot.sessionID,
                taskID: prepared.snapshot.taskID, generation: prepared.snapshot.generation,
                method: "attachmentDraftSave", argumentsJSON: original)
            let envelope = try NativeJSON.jsonObject(with: Data(prepared.envelopeJSON.utf8))
            let wrapper = try Self.ownedJSON(["version": 1, "recordSHA256": prepared.fingerprint, "envelope": envelope])
            let command = PendingCommand(version: 2, method: Self.ownedSaveMethod,
                argumentsJSON: try Self.ownedJSON([wrapper]), editorDraft: attempt)
            try preflightOwnedSave(command, snapshot: prepared.snapshot, result: prepared.resultJSON)
            try requireUnfrozenOwnedSave(prepared)
            guard try ownedJournalIsAbsent() else { throw Self.ownedSaveFailure }
            try editorDrafts.freezeOwnedSaveMatching(expected: prepared.snapshot, attempt: attempt)
            #if DEBUG
            try attachmentDraftHooks?.boundary?(.afterSaveFreeze)
            #endif
            pending = command
            try persist(command)
            #if DEBUG
            try attachmentDraftHooks?.boundary?(.afterSaveJournal)
            try attachmentDraftHooks?.boundary?(.beforeSaveCommit)
            #endif
            let captured = try requireOwnedSaveInvocation(command)
            let terminal: TerminalResult
            do { terminal = .success(try invoke(command.method, arguments: [captured.envelopeJSON])) }
            catch let failure as HostFailure {
                guard isDefiniteRejection(failure.message, method: command.method) else { throw failure }
                terminal = .rejected(failure.message)
            }
            #if DEBUG
            try attachmentDraftHooks?.boundary?(.afterSaveCommit)
            #endif
            return try finishOwnedSave(command, with: terminal).value()
        } catch let known as CoreHostAttachmentCleanupPending { throw known }
        catch let rejected as CoreHostRejection { throw rejected }
        catch { throw Self.ownedSaveFailure }
    }

    /// A crash after freeze and before journal creation proves no invocation
    /// only through demonstrable journal absence, never through a read error.
    private func reconcileUnjournaledOwnedSave(snapshot: EditorDraftSnapshot, attempt: EditorDraftAttempt) throws {
        guard pending == nil, try ownedJournalIsAbsent(),
              let binding = try NativeAttachmentDraftStore(databaseURL: databaseURL).readVersioned() else { throw Self.ownedSaveFailure }
        switch binding.record {
        case .legacy(let record):
            guard Self.ownedEqual(record.session.checkpoint, snapshot) else { throw Self.ownedSaveFailure }
            _ = try NativeAttachmentDraftStore.ownedSaveFingerprint(record)
        case .availability(let record):
            guard Self.ownedEqual(record.session.checkpoint, snapshot), let runtime = context, let jobs = attachmentJobs else { throw Self.ownedSaveFailure }
            _ = try Self.completeOriginalRequest(attempt)
            let turn = MixedSaveTurn(generation: attachmentGeneration, runtime: runtime, jobs: jobs, record: binding,
                editor: try mixedSaveFileBinding(editorDrafts.url, maximumBytes: 3_000_000))
            func requireExactOwner() throws {
                try requireMixedSaveOwner(turn, cancellation: NativeAttachmentCancellation())
                guard pending == nil, !recoveryActivationPending, try ownedJournalIsAbsent(),
                      let actual = try NativeAttachmentDraftStore(databaseURL: databaseURL).readVersioned(), binding.matches(actual),
                      try mixedSaveFileBinding(editorDrafts.url, maximumBytes: 3_000_000) == turn.editor,
                      let current = try editorDrafts.read(), Self.ownedEqual(current.snapshot, snapshot),
                      current.attempt.map({ Self.ownedEqual($0, attempt) }) == true else { throw Self.ownedSaveFailure }
            }
            try requireExactOwner()
            let lineage = try NativeAttachmentDraftCoordinator.availabilitySaveLineageJSON(record, managedDirectoryURI: mixedSaveManagedURI())
            _ = try invoke("attachmentDraftValidateLineageV5", arguments: [lineage]); try requireExactOwner()
            try editorDrafts.preflightOwnedSave(expected: snapshot, attempt: attempt)
            try editorDrafts.thawOwnedSaveMatching(expected: snapshot, attempt: attempt)
            return
        case .mixed(let record):
            guard Self.ownedEqual(record.session.checkpoint, snapshot) else { throw Self.ownedSaveFailure }
            guard let runtime = context, let jobs = attachmentJobs else { throw Self.ownedSaveFailure }
            let cancellation = NativeAttachmentCancellation()
            let turn = MixedSaveTurn(generation: attachmentGeneration, runtime: runtime, jobs: jobs, record: binding,
                editor: try mixedSaveFileBinding(editorDrafts.url, maximumBytes: 3_000_000))
            func requireExactOwner() throws {
                try requireMixedSaveOwner(turn, cancellation: cancellation)
                guard pending == nil, !recoveryActivationPending, try ownedJournalIsAbsent(),
                      let actual = try NativeAttachmentDraftStore(databaseURL: databaseURL).readVersioned(), binding.matches(actual),
                      try mixedSaveFileBinding(editorDrafts.url, maximumBytes: 3_000_000) == turn.editor,
                      let current = try editorDrafts.read(), Self.ownedEqual(current.snapshot, snapshot),
                      current.attempt.map({ Self.ownedEqual($0, attempt) }) == true else { throw Self.ownedSaveFailure }
            }
            try requireExactOwner()
            let selection: NativeAttachmentDraftCoordinator.MixedSaveSelection
            if (try? Self.completeOriginalRequest(attempt)) != nil { selection = record.version == 4 ? .completeHash : .complete }
            else { _ = try Self.ownedOriginalRequest(attempt); selection = .legacy }
            let lineage = try NativeAttachmentDraftCoordinator.mixedSaveLineageJSON(record,
                managedDirectoryURI: mixedSaveManagedURI(), selection: selection)
            _ = try invoke(record.version == 4 ? "attachmentDraftValidateLineageV4" : "attachmentDraftValidateLineageV3", arguments: [lineage])
            try editorDrafts.preflightOwnedSave(expected: snapshot, attempt: attempt)
            try requireExactOwner()
            try editorDrafts.thawOwnedSaveMatching(expected: snapshot, attempt: attempt)
            return
        }
        _ = try Self.ownedOriginalRequest(attempt)
        try editorDrafts.preflightOwnedSave(expected: snapshot, attempt: attempt)
        try editorDrafts.thawOwnedSaveMatching(expected: snapshot, attempt: attempt)
    }

    private func requireOwnedCleanup(_ command: PendingCommand, editorAbsent: Bool = false,
                                     sidecarAbsent: Bool = false) throws -> OwnedSaveJournal {
        let captured = try ownedSaveJournal(command)
        try requireOwnedJournalOnDisk(command)
        if editorAbsent { guard try editorDrafts.read() == nil else { throw Self.ownedSaveFailure } }
        if sidecarAbsent { guard captured.record == nil else { throw Self.ownedSaveFailure } }
        return captured
    }

    private func clearOwnedSavePending(_ command: PendingCommand, success: Bool) throws {
        _ = try requireOwnedCleanup(command, editorAbsent: success, sidecarAbsent: success)
        #if DEBUG
        try attachmentDraftHooks?.boundary?(.beforeSaveJournalClear)
        try faults?.journalRemove?()
        #endif
        _ = try requireOwnedCleanup(command, editorAbsent: success, sidecarAbsent: success)
        try DurableFile.remove(journalURL)
        #if DEBUG
        try attachmentDraftHooks?.boundary?(.afterSaveJournalClear)
        #endif
        let captured = try ownedSaveJournal(command)
        if success {
            guard captured.record == nil, try editorDrafts.read() == nil else { throw Self.ownedSaveFailure }
        }
        guard try ownedJournalIsAbsent() else { throw Self.ownedSaveFailure }
        pending = nil
    }

    private func finishOwnedSave(_ command: PendingCommand, with terminal: TerminalResult) throws -> TerminalResult {
        let result: String?
        if case .success(let value) = terminal {
            _ = try validateOwnedSaveAcknowledgement(command, value: value)
            result = value
        } else {
            _ = try validateOwnedSaveAcknowledgement(command)
            if case .rejected(let message) = terminal {
                guard isDefiniteRejection(message, method: command.method) else { throw Self.ownedSaveFailure }
            }
            result = nil
        }
        var finished = command; finished.terminal = terminal
        pending = finished
        #if DEBUG
        try attachmentDraftHooks?.boundary?(.beforeSaveTerminal)
        #endif
        // No cleanup authority exists until this exact terminal reaches disk.
        try persist(finished)
        do {
            #if DEBUG
            try attachmentDraftHooks?.boundary?(.afterSaveTerminal)
            #endif
            let captured = try requireOwnedCleanup(finished)
            if result != nil {
                #if DEBUG
                try attachmentDraftHooks?.boundary?(.beforeSaveEditorDetach)
                try faults?.editorDraftRemove?()
                #endif
                _ = try requireOwnedCleanup(finished)
                try editorDrafts.removeOwnedSaveMatching(expected: captured.snapshot, attempt: captured.attempt)
                #if DEBUG
                try attachmentDraftHooks?.boundary?(.afterSaveEditorDetach)
                #endif
                _ = try requireOwnedCleanup(finished, editorAbsent: true)
                if let record = captured.record {
                    let coordinator = try ownedSaveCoordinatorForWork()
                    for (index, op) in record.operations.enumerated() {
                        // An already absent sidecar authorizes no further file job.
                        guard try requireOwnedCleanup(finished, editorAbsent: true).record != nil else { break }
                        #if DEBUG
                        try attachmentDraftHooks?.boundary?(.beforeSaveStage(index))
                        #endif
                        guard try requireOwnedCleanup(finished, editorAbsent: true).record != nil else { break }
                        try coordinator.retireOwnedSaveStage(op)
                        #if DEBUG
                        try attachmentDraftHooks?.boundary?(.afterSaveStage(index))
                        #endif
                        _ = try requireOwnedCleanup(finished, editorAbsent: true)
                    }
                    coordinator.drainOwnedSaveJobs()
                }
                #if DEBUG
                try attachmentDraftHooks?.boundary?(.beforeSaveRelease)
                #endif
                _ = try requireOwnedCleanup(finished, editorAbsent: true)
                try NativeAttachmentDraftStore(databaseURL: databaseURL).releaseSavedAddsMatching(fingerprint: captured.fingerprint)
                #if DEBUG
                try attachmentDraftHooks?.boundary?(.afterSaveRelease)
                #endif
                _ = try requireOwnedCleanup(finished, editorAbsent: true, sidecarAbsent: true)
                try clearOwnedSavePending(finished, success: true)
                _ = try? invoke("attachmentDraftAcknowledged", arguments: ["save", "confirmed"])
            } else {
                #if DEBUG
                try attachmentDraftHooks?.boundary?(.beforeSaveThaw)
                #endif
                _ = try requireOwnedCleanup(finished)
                try editorDrafts.thawOwnedSaveMatching(expected: captured.snapshot, attempt: captured.attempt)
                #if DEBUG
                try attachmentDraftHooks?.boundary?(.afterSaveThaw)
                #endif
                _ = try requireOwnedCleanup(finished)
                try clearOwnedSavePending(finished, success: false)
            }
        } catch {
            if let result { throw CoreHostAttachmentCleanupPending(resultJSON: result) }
            throw Self.ownedSaveFailure
        }
        return terminal
    }
    func readAttachmentDraft() throws -> String {
        dispatchPrecondition(condition: .onQueue(queue))
        guard started, !closed else { throw HostFailure("Attachment draft recovery is not ready") }
        // Reading private evidence does not activate or replay pending domain work.
        do { return try NativeAttachmentDraftCoordinator.readSummary(databaseURL: databaseURL) }
        catch { throw HostFailure("Attachment draft capability is unavailable") }
    }
    func addAttachmentDraft(requestJSON: String, cancellation: NativeAttachmentCancellation) throws -> String {
        try attachmentDraftOperation { try attachmentDraftCoordinator().add(requestJSON, cancellation: cancellation) }
    }
    func recoverAttachmentDraft(expectedSession: String, cancellation: NativeAttachmentCancellation) throws -> String {
        try attachmentDraftOperation { try attachmentDraftCoordinator().recover(session: expectedSession, cancellation: cancellation) }
    }
    func discardAttachmentDraft(requestJSON: String) throws -> String {
        try attachmentDraftOperation { try attachmentDraftCoordinator().discard(requestJSON) }
    }

    func readEditorDraft() throws -> EditorDraftSnapshot? {
        dispatchPrecondition(condition: .onQueue(queue))
        guard started, !closed, pending == nil else { throw HostFailure("Editor draft recovery is not settled") }
        guard let current = try editorDrafts.read() else { return nil }
        if attachmentDraftEvidence, (try? retainedOrdinaryOwner()) != nil {
            let owns = try beginRetainedOrdinaryTurn(attempt: current.attempt)
            defer { if owns && pending == nil { retainedOrdinaryTurn = nil } }
            try requireRetainedOrdinaryTurn()
            if let attempt = current.attempt {
                guard try ownedJournalIsAbsent() else { throw Self.retainedOrdinaryFailure }
                try editorDrafts.thaw(attempt)
                try refreshOrdinaryEditor(snapshot: current.snapshot, attempt: nil)
            }
            try requireRetainedOrdinaryTurn()
            return current.snapshot
        }
        if attachmentDraftEvidence {
            // Preserve the historical owned-editor read/reconcile path, but a
            // foreign independent editor cannot borrow a corrupt, decided or
            // otherwise nonqualified owner's presence to reopen ordinary work.
            guard let owner = try NativeAttachmentDraftStore(databaseURL: databaseURL).readVersioned() else {
                throw Self.retainedOrdinaryFailure
            }
            let session: NativeAttachmentDraftStore.Session
            switch owner.record {
            case .legacy(let record): session = record.session
            case .mixed(let record): session = record.session
            case .availability(let record): session = record.session
            }
            guard Self.ownedEqual(current.snapshot.sessionID, session.sessionID),
                  Self.ownedEqual(current.snapshot.taskID, session.taskID) else { throw Self.retainedOrdinaryFailure }
        }
        if let attempt = current.attempt {
            if attempt.method == "attachmentDraftSave" {
                try reconcileUnjournaledOwnedSave(snapshot: current.snapshot, attempt: attempt)
                return current.snapshot
            }
            try requireNoAttachmentDraft()
            // No journal means the invocation never began, or a definite refusal settled.
            try editorDrafts.thaw(attempt)
        }
        return current.snapshot
    }

    func checkpointEditorDraft(_ snapshot: EditorDraftSnapshot) throws {
        guard providerCopy?.receipt != nil || providerCopy == nil else { throw HostFailure("Attachment provider is loading") }
        dispatchPrecondition(condition: .onQueue(queue))
        guard started, !closed, pending == nil else { throw HostFailure("Editor draft is not ready") }
        if attachmentDraftEvidence {
            if (try? retainedOrdinaryOwner()) != nil {
                let owns = try beginRetainedOrdinaryTurn()
                defer { if owns && pending == nil { retainedOrdinaryTurn = nil } }
                guard let turn = retainedOrdinaryTurn, !Self.ownedEqual(snapshot.sessionID, turn.session) else {
                    throw Self.retainedOrdinaryFailure
                }
                try requireRetainedOrdinaryTurn()
                try editorDrafts.checkpoint(snapshot)
                try refreshOrdinaryEditor(snapshot: snapshot, attempt: nil)
                return
            }
            guard let loaded = try NativeAttachmentDraftStore(databaseURL: databaseURL).readVersioned() else {
                throw HostFailure("Attachment draft ownership requires exact recovery")
            }
            _ = try attachmentDraftOperation {
                switch loaded.record {
                case .legacy(let record):
                    guard record.version == 2 else { throw HostFailure("Attachment draft ownership requires exact recovery") }
                    try attachmentDraftCoordinator().advance(snapshot)
                case .mixed:
                    let cancellation = NativeAttachmentCancellation()
                    try attachmentDraftCoordinatorV3(cancellation: cancellation).advanceV3(snapshot, cancellation: cancellation)
                case .availability:
                    let cancellation = NativeAttachmentCancellation()
                    try attachmentDraftCoordinatorV3(cancellation: cancellation).advanceV5(snapshot, cancellation: cancellation)
                }
                return ""
            }
            return
        }
        try requireNoAttachmentDraft()
        try editorDrafts.checkpoint(snapshot)
        try requireNoAttachmentDraft()
    }

    func discardEditorDraft(expectedSession: String) throws {
        guard providerCopy?.receipt != nil || providerCopy == nil else { throw HostFailure("Attachment provider is loading") }
        dispatchPrecondition(condition: .onQueue(queue))
        guard started, !closed, pending == nil else { throw HostFailure("Editor Save must settle before discard") }
        let owns = try beginRetainedOrdinaryTurn()
        defer { if owns && pending == nil { retainedOrdinaryTurn = nil } }
        if let turn = retainedOrdinaryTurn {
            guard let editor = turn.editor, editor.attempt == nil,
                  Self.ownedEqual(editor.snapshot.sessionID, expectedSession) else { throw Self.retainedOrdinaryFailure }
        }
        try requireOrdinaryEditorMutation()
        try editorDrafts.discard(sessionID: expectedSession)
        try refreshOrdinaryEditor(snapshot: nil, attempt: nil)
    }

    func discardCorruptEditorDraft() throws {
        dispatchPrecondition(condition: .onQueue(queue))
        try requireNoAttachmentDraft()
        // A failed start may not yet have assigned `pending`. Inspect the durable
        // journal itself before removing the only frozen proof of an editor Save.
        let saved = try loadPendingJournal(checkingEditorSnapshot: false)
        let editorMethods: Set<String> = ["draftCommit", "checklistPreparedCommit", "taskPromoteCommit"]
        if let pending, pending.editorDraft != nil || editorMethods.contains(pending.method) {
            guard let saved, saved.method == pending.method,
                  saved.editorDraft == pending.editorDraft else {
                throw HostFailure("Pending editor Save has no matching durable terminal proof")
            }
        }
        if let saved, saved.editorDraft != nil || editorMethods.contains(saved.method) {
            guard let terminal = saved.terminal, case .success = terminal else {
                throw HostFailure("Pending editor Save requires its frozen snapshot")
            }
        }
        try editorDrafts.discardCorrupt()
    }

    private static func editorRequestTaskID(_ method: String, _ request: [String: Any]) -> String? {
        if method == "taskDelete" || method == "taskPromote" { return request["taskId"] as? String }
        if method == "boardAction" {
            guard Set(request.keys) == Set(["requestId", "action"]),
                  let action = request["action"] as? [String: Any],
                  Set(action.keys) == Set(["type", "taskId"]),
                  action["type"] as? String == "duplicateTask" else { return nil }
            return action["taskId"] as? String
        }
        return request["id"] as? String
    }

    func saveEditorDraft(_ method: String, argumentsJSON: String,
                         expectedSession: String, expectedGeneration: Int) throws -> String {
        dispatchPrecondition(condition: .onQueue(queue))
        guard started, !closed, pending == nil, ["saveDraft", "checklistSave", "boardAction", "taskDelete", "taskPromote"].contains(method) else {
            throw HostFailure("Editor Save is not ready")
        }
        let owns = try beginRetainedOrdinaryTurn()
        defer { if owns && pending == nil { retainedOrdinaryTurn = nil } }
        try requireOrdinaryEditorMutation()
        let args = try arguments(method, argumentsJSON)
        guard let encoded = args.first as? String,
              let request = try NativeJSON.jsonObject(with: Data(encoded.utf8)) as? [String: Any],
              let id = Self.editorRequestTaskID(method, request),
              method != "saveDraft" || request["scheduleBase"] != nil,
              let current = try editorDrafts.read(), current.snapshot.taskID == id else {
            throw HostFailure("Editor Save request does not match its draft")
        }
        guard method != "taskDelete" || request["source"] as? String != "reference" else {
            throw CoreHostRejection(message: "INVALID_INPUT: Reference row Delete cannot carry an editor draft")
        }
        let attempt = try editorDrafts.freeze(sessionID: expectedSession, generation: expectedGeneration,
                                              method: method, argumentsJSON: argumentsJSON)
        try refreshOrdinaryEditor(snapshot: current.snapshot, attempt: attempt)
        let value: String
        do {
            value = try call(method, argumentsJSON: argumentsJSON, editorAttempt: attempt)
        } catch {
            // A command that never entered the journal, or a definite refusal,
            // cannot have written. Keep uncertain attempts frozen for exact replay.
            if pending == nil {
                try requireOrdinaryEditorMutation()
                guard try ownedJournalIsAbsent() else { throw Self.retainedOrdinaryFailure }
                try editorDrafts.thaw(attempt)
                try refreshOrdinaryEditor(snapshot: current.snapshot, attempt: nil)
            }
            throw error
        }
        // A prepared draft no-op returns before a journal exists. Cleanup errors
        // leave the frozen file for explicit read/retry, without another writer.
        if pending == nil, let current = try editorDrafts.read() {
            guard current.attempt == attempt else { throw HostFailure("Editor draft Save attempt changed") }
            #if DEBUG
            try faults?.editorDraftRemove?()
            #endif
            try requireOrdinaryEditorMutation()
            try editorDrafts.removeMatching(attempt)
            try refreshOrdinaryEditor(snapshot: nil, attempt: nil)
        }
        try requireRetainedOrdinaryTurn()
        return value
    }

    func diagnosticsFileAction(_ method: String) throws -> String {
        dispatchPrecondition(condition: .onQueue(queue))
        guard started, !closed, !recoveryActivationPending,
              ["logShare", "logClearChecked"].contains(method) else {
            throw HostFailure("Diagnostics file action unavailable")
        }
        // No pending check or mutation here: the file queue is independent from
        // an already initialized host's exact owed domain command.
        return try invoke(method, arguments: [])
