        let result = try Self.ownedJSON(["version": 1, "tasks": groups["tasks"]!, "projects": groups["projects"]!])
        guard result.utf8.count <= 16 * 1024 * 1024 else { throw Self.cleanupFailure }
        try requireCleanupTurn(); return result
    }
