                return value
            }
            let authority = try options()
            func liveProject() throws {
                guard Self.equalJSON(try options(), authority) else { throw failure }
            }
            guard let project = authority["project"] as? [String: Any],
                  let attachments = project["attachments"] as? [[String: Any]] else { throw failure }
            let matches = attachments.filter { ($0["id"] as? String).map { Self.ownedEqual($0, selectedID) } == true }
            guard matches.count == 1, let selected = matches.first, selected["kind"] as? String == "file",
                  selected["deletedAt"] == nil, let uri = selected["uri"] as? String, !uri.isEmpty else { throw failure }
            relocatedURI = try relocatedFileOpenURI(selected)
            if relocatedURI != nil {
                try requireNoAttachmentDraft()
                relocatedEditor = try mixedSaveFileBinding(editorDrafts.url, maximumBytes: 3_000_000)
                relocatedRow = try relocatedFileOpenRow(table: "projects", id: projectID, selected: selected)
                relocatedSelected = selected; relocatedID = projectID
                try owner()
            }
            let observedURI = relocatedURI ?? uri
            let coordinator = try NativeAttachmentDraftCoordinator(databaseURL: databaseURL, jobs: jobs,
                requireOwner: owner, invoke: { [unowned self] name, args in try self.invoke(name, arguments: args) })
            let before = try coordinator.snapshotFileOpen(attachmentID: selectedID, targetURI: observedURI, cancellation: cancellation)
            if relocatedURI != nil { try relocatedFileOpenProof(before, selected: selected) }
            try liveProject()
            let result = try invoke("projectLocalFileOpenPlan", arguments: [requestJSON, before != nil], localCancellation: cancellation)
            try liveProject()
            guard result.utf8.count <= 6_400_000,
                  let answer = try NativeJSON.jsonObject(with: Data(result.utf8)) as? [String: Any],
                  Set(answer.keys) == Set(["status", "message", "update", "open"]), answer["update"] is NSNull,
                  let status = answer["status"] as? String,
                  status == (before == nil ? "unavailable" : "available") else { throw failure }
            if status == "available" {
                guard answer["message"] is NSNull, let plan = answer["open"] as? [String: Any],
                      let kind = plan["kind"] as? String else { throw failure }
                switch kind {
                case "file":
                    guard Set(plan.keys) == Set(["kind", "uri", "mimeType", "viewMimeType"]),
                          let plannedURI = plan["uri"] as? String, Self.ownedEqual(plannedURI, uri),
                          plan["mimeType"] is NSNull || plan["mimeType"] is String, plan["viewMimeType"] is String else { throw failure }
                case "image":
                    guard Set(plan.keys) == Set(["kind", "attachment"]), let item = plan["attachment"] as? [String: Any],
                          let id = item["id"] as? String, Self.ownedEqual(id, selectedID), item["kind"] as? String == "file",
                          item["deletedAt"] == nil, let plannedURI = item["uri"] as? String, Self.ownedEqual(plannedURI, uri),
                          Self.equalJSON(item, selected) else { throw failure }
                default: throw failure
                }
            } else {
                guard answer["open"] is NSNull, answer["message"] is String else { throw failure }
            }
            let after = try coordinator.snapshotFileOpen(attachmentID: selectedID, targetURI: observedURI, cancellation: cancellation)
            if relocatedURI != nil { try relocatedFileOpenProof(after, selected: selected) }
            guard before == after else { throw failure }
            try liveProject()
            if status == "available" {
                _ = try? invoke("attachmentDraftAcknowledged", arguments: ["project-file-open", "prepared"])
                try liveProject()
            }
            try owner()
            if let relocatedURI, status == "available" {
                let resolved = try relocatedFileOpenResult(result, originalURI: uri, currentURI: relocatedURI)
                _ = try? invoke("attachmentDraftAcknowledged", arguments: ["relocated-project-file-open", "prepared"])
                try liveProject(); try owner()
                guard try coordinator.snapshotFileOpen(attachmentID: selectedID, targetURI: observedURI, cancellation: cancellation) == before else { throw failure }
                try owner()
                return resolved
            }
            return result
        } catch {
            if cancellation.isCancelled || error is CancellationError { throw CancellationError() }
            throw failure
        }
    }

    func localAttachmentRequest(name: String, requestJSON: String, cancellation: NativeAttachmentCancellation) throws -> String {
        dispatchPrecondition(condition: .onQueue(queue))
        guard started, !closed, !recoveryActivationPending, pending == nil, projectFileAddTurn == nil else {
            throw HostFailure("Core host is not ready; retry startup")
        }
        guard attachmentJobs != nil else { throw HostFailure("Attachment file operation is unavailable") }
        if ["draftAddFile", "draftRemove", "settleTaskDraftAttachments"].contains(name) { try requireNoAttachmentDraft() }
        if cancellation.isCancelled { throw CancellationError() }
        guard requestJSON.utf8.count <= 6_400_000,
              let request = try? NativeJSON.jsonObject(with: Data(requestJSON.utf8)) as? [String: Any] else {
            throw HostFailure("INVALID_INPUT: Local attachment request is invalid")
        }
        func text(_ value: Any?, limit: Int = 500, nonempty: Bool = true) -> Bool {
            guard let value = value as? String else { return false }
            return value.utf16.count <= limit && (!nonempty || !value.isEmpty)
        }
        func uuid(_ value: Any?) -> Bool {
            guard let value = value as? String else { return false }
            return UUID(uuidString: value)?.uuidString.lowercased() == value
        }
        let valid: Bool
        switch name {
        case "draftAddFile":
            let picked = request["picked"] as? [String: Any] ?? [:]
            let nullableName = picked["name"] is NSNull || text(picked["name"], limit: 100_000, nonempty: false)
            let nullableMime = picked["mimeType"] is NSNull || text(picked["mimeType"], nonempty: false)
            let size = picked["size"] as? NSNumber
            let validSize = picked["size"] is NSNull || (size != nil && CFGetTypeID(size!) != CFBooleanGetTypeID()
                && size!.doubleValue.isFinite && size!.doubleValue >= 0)
            valid = Set(request.keys) == Set(["requestId", "owner", "source", "picked"])
                && uuid(request["requestId"]) && Self.validTaskAttachmentOwner(request["owner"])
                && ["file", "image"].contains(request["source"] as? String ?? "")
                && Set(picked.keys) == Set(["uri", "name", "mimeType", "size"])
                && text(picked["uri"], limit: 16 * 1024) && nullableName && nullableMime && validSize
        case "draftRemove":
            valid = Set(request.keys) == Set(["requestId", "owner", "attachmentId"])
                && uuid(request["requestId"]) && Self.validTaskAttachmentOwner(request["owner"])
                && text(request["attachmentId"])
        case "openAttachment":
            valid = Set(request.keys) == Set(["owner", "attachmentId"])
                && Self.validTaskAttachmentOwner(request["owner"]) && text(request["attachmentId"])
        case "settleTaskDraftAttachments":
            valid = Set(request.keys) == Set(["taskId", "taskRevision", "baseline", "draft", "committed"])
                && text(request["taskId"]) && text(request["taskRevision"], limit: 100_000, nonempty: false)
                && ["baseline", "draft", "committed"].allSatisfy { Self.validTaskAttachmentList(request[$0]) }
        default: valid = false
        }
        guard valid else { throw HostFailure("INVALID_INPUT: Local attachment request is invalid") }
        do {
            let result = try invoke("attachmentRequest", arguments: [name, requestJSON], localCancellation: cancellation)
            guard result.utf8.count <= 6_400_000,
                  (try? NativeJSON.jsonObject(with: Data(result.utf8))) is [String: Any] else {
                throw HostFailure("Local attachment operation failed")
            }
            return result
        } catch is CancellationError { throw CancellationError() }
        catch { throw HostFailure("Local attachment operation failed") }
    }

    private func settleTaskDownloadTicket(_ id: String, terminalConsumed: Bool, turn: TaskDownloadTurn,
                                          runtime: JSContext, host: JSValue) {
        // Failure retires only this submission. Ports stay revoked while the
        // accepted workers and the exact shared ticket reach terminal state.
        turn.preparing = false
        runtime.exception = nil
        _ = host.invokeMethod("cancel", withArguments: [id])
        runtime.exception = nil
        attachmentJobs?.cancelAndDrain()
        httpJobs?.cancelAndDrain()
        secretJobs?.drain()
        cryptoJobs?.drain()
        if !terminalConsumed {
            while true {
                _ = runtime.objectForKeyedSubscript("__pumpTimers")?.call(withArguments: [])
                runtime.exception = nil
                let reply = host.invokeMethod("poll", withArguments: [id])
                runtime.exception = nil
                if let reply, !reply.isNull, !reply.isUndefined { break }
                let delay = runtime.objectForKeyedSubscript("__nextTimerDelay")?.call(withArguments: [])?.toDouble() ?? 1
                runtime.exception = nil
                Thread.sleep(forTimeInterval: delay.isFinite && delay > 0 ? min(delay, 10) / 1_000 : 0.001)
            }
        }
        _ = runtime.objectForKeyedSubscript("__pumpTimers")?.call(withArguments: [])
        runtime.exception = nil
        _ = runtime.objectForKeyedSubscript("__resumeHostCalls")?.call(withArguments: [])
        // Settlement must not replace the original owner/parse/cancel failure.
        runtime.exception = nil
    }

    private func invoke(_ method: String, arguments: [Any], localCancellation: NativeAttachmentCancellation? = nil) throws -> String {
        try denyCleanupOwner()
        try requireRetainedOrdinaryTurn(requirePreparation: true)
        try requireProjectFileAddTurn()
        try requireTaskDownloadTurn(before: taskDownloadTurn?.preparing == true)
        guard let context, let host = context.objectForKeyedSubscript("MindwtrHost") else { throw HostFailure("Core runtime unavailable") }
        invoking = true
        defer { invoking = false; scheduleAttachmentIdle(immediate: true) }
        let selectedTurn = taskDownloadTurn
        var selectedTicket: String?, selectedSucceeded = false, terminalConsumed = false
        defer {
            if let selectedTurn, !selectedSucceeded, let selectedTicket {
                settleTaskDownloadTicket(selectedTicket, terminalConsumed: terminalConsumed, turn: selectedTurn, runtime: context, host: host)
            }
        }
        context.exception = nil
        let ticket: JSValue?
        if method == "dataSetting" {
            guard arguments.count == 1, let originalRequest = arguments.first as? String else {
                throw HostFailure("INVALID_INPUT: Invalid Data setting request")
            }
            // The journal retains its original method and raw request. The
            // shared host exposes this exact existing command through its menu dispatcher.
            ticket = host.invokeMethod("menuCommand", withArguments: ["dataSetting", originalRequest])
        } else {
            ticket = host.invokeMethod(method, withArguments: arguments)
        }
        // Capture a trusted submitted ticket before observing a synchronous
        // exception so an accepted selected call is still cancelled and polled.
        if selectedTurn != nil, let ticket, ticket.isString, let id = ticket.toString(), Int(id).map({ $0 > 0 }) == true {
            selectedTicket = id
        }
        try checkException()
        guard let ticket, ticket.isString, let id = ticket.toString(), Int(id).map({ $0 > 0 }) == true else {
            throw HostFailure("Malformed core request ticket")
        }
        // No timeout abandons a command while its durable result is unknown.
        // Promise jobs drain whenever JSC returns from a call; timers share this queue.
        var cancelled = false
        defer {
            if cancelled && selectedTurn == nil {
                attachmentJobs?.cancelAndDrain()
                httpJobs?.cancelAndDrain()
                secretJobs?.drain()
                _ = context.objectForKeyedSubscript("__pumpTimers")?.call(withArguments: [])
                _ = context.objectForKeyedSubscript("__resumeHostCalls")?.call(withArguments: [])
                context.exception = nil
            }
        }
        while true {
            var reply: JSValue?
            if !cancelled, localCancellation?.isCancelled == true {
                // An already acknowledged terminal result wins the cancellation
                // race; do not report failure after its completion diagnostic.
                reply = host.invokeMethod("poll", withArguments: [id])
                try checkException()
                if reply == nil || reply!.isNull || reply!.isUndefined {
                    cancelled = true
                    _ = host.invokeMethod("cancel", withArguments: [id])
                    try checkException()
                    // Completes uninterruptible RN installer work before allowing
                    // another operation or library owner to observe the namespace.
                    attachmentJobs?.cancelAndDrain()
                    httpJobs?.cancelAndDrain()
                    secretJobs?.drain()
                    if selectedTurn != nil { cryptoJobs?.drain() }
                }
            }
            if reply == nil || reply!.isNull || reply!.isUndefined {
                _ = context.objectForKeyedSubscript("__pumpTimers")?.call(withArguments: [])
                try checkException()
                #if DEBUG
                if localCancellation != nil { attachmentHooks?.pump?() }
                #endif
                reply = host.invokeMethod("poll", withArguments: [id])
                try checkException()
            }
            if let reply, !reply.isNull, !reply.isUndefined {
                // poll has already removed this ticket, even if parsing or the
                // post-terminal owner fence refuses its returned value.
                terminalConsumed = true
                guard reply.isString, let json = reply.toString(),
                      let envelope = try NativeJSON.jsonObject(with: Data(json.utf8)) as? [String: Any],
                      let ok = envelope["ok"] as? Bool else { throw HostFailure("Malformed core response") }
                if cancelled {
                    throw CancellationError()
                }
                if !ok { throw HostFailure(envelope["error"] as? String ?? "Core command failed") }
                guard let value = envelope["value"] else { throw HostFailure("Core response has no value") }
                try requireRetainedOrdinaryTurn(requirePreparation: true)
        try requireProjectFileAddTurn()
                try requireTaskDownloadTurn(before: taskDownloadTurn?.preparing == true)
                let result = String(decoding: try JSONSerialization.data(withJSONObject: value, options: [.fragmentsAllowed]), as: UTF8.self)
                selectedSucceeded = true
                return result
            }
            try requireRetainedOrdinaryTurn(requirePreparation: true)
        try requireProjectFileAddTurn()
            try requireTaskDownloadTurn(before: taskDownloadTurn?.preparing == true)
            let delay = context.objectForKeyedSubscript("__nextTimerDelay")?.call(withArguments: [])?.toDouble() ?? 1
            try checkException()
            Thread.sleep(forTimeInterval: delay.isFinite && delay > 0 ? min(delay, 10) / 1_000 : 0.001)
        }
    }

    private func scheduleAttachmentIdle(immediate: Bool = false) {
        guard started, !closed, !invoking, !recoveryActivationPending, pending == nil,
              !cleanupOwed, taskDownloadTurn == nil,
              attachmentJobs != nil || httpJobs != nil || secretJobs != nil || cryptoJobs != nil, let context else { return }
        let delay = immediate ? 0 : context.objectForKeyedSubscript("__nextTimerDelay")?.call(withArguments: [])?.toDouble() ?? -1
        guard delay.isFinite, delay >= 0 else { return }
        // One scheduled idle turn per generation; completions can move a timer
        // earlier but never capture a JSContext/JSValue on the worker queue.
        if attachmentIdlePump != nil && !immediate { return }
        attachmentIdlePump?.cancel()
        let generation = attachmentGeneration
        let item = DispatchWorkItem { [weak self] in self?.pumpAttachmentIdle(generation: generation) }
        attachmentIdlePump = item
        queue.asyncAfter(deadline: .now() + min(delay, 60_000) / 1_000, execute: item)
    }

    private func pumpAttachmentIdle(generation: UInt64) {
        dispatchPrecondition(condition: .onQueue(queue))
        guard generation == attachmentGeneration else { return }
        attachmentIdlePump = nil
        guard started, !closed, !invoking, !recoveryActivationPending, pending == nil, !cleanupOwed, taskDownloadTurn == nil, let context else { return }
        _ = context.objectForKeyedSubscript("__pumpTimers")?.call(withArguments: [])
        // No arbitrary JS exception content enters diagnostics.
        if context.exception != nil { context.exception = nil }
        scheduleAttachmentIdle()
    }

    private func checkException() throws {
        if let exception = context?.exception {
            let message = exception.toString() ?? "JavaScriptCore exception"
            context?.exception = nil
            throw HostFailure(message)
        }
    }

    private func ordinaryGuardedSQL(_ sql: String, parameters: String? = nil) throws -> String {
        try denyCleanupOwner()
        guard taskDownloadTurn == nil else { throw Self.taskDownloadFailure }
        try requireRetainedOrdinaryTurn(requirePreparation: true)
        try requireProjectFileAddTurn()
        let result: String
        if let parameters { result = try requireDatabase().execute(sql, parametersJSON: parameters) }
        else { result = try requireDatabase().execute(sql) }
        try requireRetainedOrdinaryTurn(requirePreparation: true)
        try requireProjectFileAddTurn()
        return result
    }

    private static var deviceStorageInvalid: HostFailure { HostFailure("Device settings input is invalid") }
    private static var deviceStorageUnavailable: HostFailure { HostFailure("Device settings storage is unavailable") }
    private static let deviceStorageFrameLimit = 12 * 1024 * 1024

    private func requireDeviceStorageAdmission() throws -> NativeDeviceKV {
        dispatchPrecondition(condition: .onQueue(queue))
        guard taskDownloadTurn == nil else { throw Self.deviceStorageUnavailable }
        try denyCleanupOwner()
        guard started, !closed, !recoveryActivationPending, pending == nil,
              retainedOrdinaryTurn == nil, projectFileAddTurn == nil, lockFD >= 0 else {
            throw Self.deviceStorageUnavailable
        }
        try requireNoAttachmentDraft()
        guard let deviceStorage else { throw Self.deviceStorageUnavailable }
        return deviceStorage
    }
    private func taskDownloadLegacyRead(_ names: [String]) throws -> [(String, String?)] {
        guard let turn = taskDownloadTurn, turn.preparing, !names.isEmpty,
              names.count <= 2, names.allSatisfy({ Self.taskDownloadLegacyKeys.contains($0) }) else { throw Self.deviceStorageUnavailable }
        try requireTaskDownloadTurn(before: true)
        let values = try turn.storage.multiGet(names)
        for (name, value) in values {
            if let existing = turn.legacy.first(where: { Self.ownedEqual($0.0, name) }) {
                guard Self.taskDownloadOptionalEqual(existing.1, value) else { throw Self.deviceStorageUnavailable }
            } else { turn.legacy.append((name, value)) }
        }
        try requireTaskDownloadTurn(before: true)
        return values
    }
    private static func deviceStorageText(_ value: JSValue) throws -> String {
        guard value.isString, let text = value.toString(), text.utf8.count <= deviceStorageFrameLimit else {
            throw deviceStorageInvalid
        }
        return text
    }
    private static func deviceStorageKeys(_ value: JSValue) throws -> [String] {
        let text = try deviceStorageText(value)
        guard let keys = try? NativeJSON.jsonObject(with: Data(text.utf8)) as? [String], keys.count <= 64 else {
            throw deviceStorageInvalid
        }
        return keys
    }
    private static func deviceStoragePairs(_ value: JSValue) throws -> [(String, String)] {
        let text = try deviceStorageText(value)
        guard let pairs = try? NativeJSON.jsonObject(with: Data(text.utf8)) as? [[Any]], pairs.count <= 64 else {
            throw deviceStorageInvalid
        }
        return try pairs.map { pair in
            guard pair.count == 2, let key = pair[0] as? String, let value = pair[1] as? String else {
                throw deviceStorageInvalid
            }
            return (key, value)
        }
    }
    private static func deviceStorageJSON(_ value: [Any], strings: [String]) throws -> String {
        var decoded = 0
        for string in strings {
            let size = string.utf8.count, next = decoded.addingReportingOverflow(string.utf8.count)
            guard size <= 1024 * 1024, !next.overflow, next.partialValue <= 8 * 1024 * 1024 else {
                throw deviceStorageUnavailable
            }
            decoded = next.partialValue
        }
        let bytes = try JSONSerialization.data(withJSONObject: value)
        guard bytes.count <= deviceStorageFrameLimit else { throw deviceStorageUnavailable }
        return String(decoding: bytes, as: UTF8.self)
    }
    private func deviceStorageResult(legacySecretRemoval: () -> Bool = { false }, _ work: () throws -> String?) -> String? {
        dispatchPrecondition(condition: .onQueue(queue))
        do {
            let result = try work()
            if taskDownloadTurn != nil { return result }
            let retiredSecret = legacySecretRemoval()
            guard let runtime = context else { throw Self.deviceStorageUnavailable }
            let generation = attachmentGeneration
            queue.async { [weak self, weak runtime] in
                guard let self, let runtime, self.attachmentGeneration == generation,
                      self.context === runtime, self.started, !self.closed, !self.invoking else { return }
                _ = runtime.objectForKeyedSubscript("MindwtrHost")?.invokeMethod("nativeDeviceStorageDelivered", withArguments: [])
                runtime.exception = nil
                if retiredSecret {
                    _ = runtime.objectForKeyedSubscript("MindwtrHost")?.invokeMethod("nativeLegacySecretRetirementDelivered", withArguments: [])
                    runtime.exception = nil
                }
                self.scheduleAttachmentIdle(immediate: true)
                #if DEBUG
                self.faults?.commandDiagnostic?("deviceStorageDelivered")
                if retiredSecret { self.faults?.commandDiagnostic?("legacySecretRetirementDelivered") }
                #endif
            }
            return result
        } catch {
            // No filesystem exception, setting name or stored value crosses JSC.
            let failure = (error as? HostFailure)?.message == Self.deviceStorageInvalid.message
                ? Self.deviceStorageInvalid : Self.deviceStorageUnavailable
            return "!MindwtrNativeError:" + failure.message
        }
    }

    private func requireHTTPAdmission(_ input: String) throws {
        dispatchPrecondition(condition: .onQueue(queue))
        try denyCleanupOwner()
        if let turn = taskDownloadTurn {
            guard input.utf8.count <= 12 * 1024 * 1024 else { throw Self.taskDownloadFailure }
            try requireTaskDownloadTurn(before: true)
            guard turn.preparing else { throw Self.taskDownloadFailure }
            guard let raw = try NativeJSON.jsonObject(with: Data(input.utf8)) as? [String: Any],
                  let url = raw["url"] as? String, Self.ownedEqual(url, turn.initialURL),
                  raw["method"] as? String == "GET", raw["text"] == nil, raw["base64"] == nil else { throw Self.taskDownloadFailure }
            return
        }
        guard started, !closed, !recoveryActivationPending, pending == nil,
              retainedOrdinaryTurn == nil, projectFileAddTurn == nil, lockFD >= 0 else {
            throw HostFailure("HTTP bridge is unavailable")
        }
        try requireNoAttachmentDraft()
    }

    private func requireSecretAdmission(_ input: String) throws {
        dispatchPrecondition(condition: .onQueue(queue))
        try denyCleanupOwner()
        if let turn = taskDownloadTurn {
            guard input.utf8.count <= 512 * 1024 else { throw Self.taskDownloadFailure }
            try requireTaskDownloadTurn(before: true)
            guard turn.preparing else { throw Self.taskDownloadFailure }
            guard let raw = try NativeJSON.jsonObject(with: Data(input.utf8)) as? [String: Any],
                  Set(raw.keys) == Set(["op", "key"]), raw["op"] as? String == "get", let account = raw["key"] as? String,
                  ["mindwtr_webdav_password", "mindwtr_sync_encryption_key_v1"].contains(account) else { throw Self.taskDownloadFailure }
            return
        }
        guard started, !closed, !recoveryActivationPending, pending == nil,
              retainedOrdinaryTurn == nil, projectFileAddTurn == nil, lockFD >= 0 else {
            throw HostFailure("Secure storage bridge is unavailable")
        }
        try requireNoAttachmentDraft()
    }

    private func requireCryptoAdmission(_ input: String) throws {
        dispatchPrecondition(condition: .onQueue(queue))
        try denyCleanupOwner()
        if let turn = taskDownloadTurn {
            guard input.utf8.count <= 12 * 1024 * 1024 else { throw Self.taskDownloadFailure }
            try requireTaskDownloadTurn(before: true)
            guard turn.preparing else { throw Self.taskDownloadFailure }
            guard let raw = try NativeJSON.jsonObject(with: Data(input.utf8)) as? [String: Any], raw["op"] as? String == "aesGcmOpen" else { throw Self.taskDownloadFailure }
            return
        }
        guard started, !closed, !recoveryActivationPending, pending == nil,
              retainedOrdinaryTurn == nil, projectFileAddTurn == nil, lockFD >= 0 else {
            throw HostFailure("Crypto bridge is unavailable")
        }
        try requireNoAttachmentDraft()
    }

    private func nextIO() throws -> String {
        try denyCleanupOwner()
        guard ioBodySource == nil else { throw HostFailure("I/O response body is unavailable") }
        func file() -> String? {
            guard let answer = attachmentJobs?.next(), !answer.isEmpty else { return nil }
            if let input = try? NativeJSON.jsonObject(with: Data(answer.utf8)) as? [String: Any], input["body"] as? Bool == true {
                ioBodySource = .file
            }
            preferredIO = 1
            return answer
        }
        func http() throws -> String? {
            guard let answer = try httpJobs?.next() else { return nil }
            if answer.body { ioBodySource = .http }
            preferredIO = 2
            return answer.json
        }
        func secret() throws -> String? {
            guard let answer = try secretJobs?.next() else { return nil }
            preferredIO = 3
            if answer.completed {
                let generation = attachmentGeneration
                queue.async { [weak self] in
                    guard let self, self.attachmentGeneration == generation, self.started, !self.closed,
                          !self.invoking, !self.cleanupOwed, let context = self.context else { return }
                    _ = context.objectForKeyedSubscript("MindwtrHost")?.invokeMethod("nativeSecretDelivered", withArguments: [])
                    context.exception = nil
                    self.scheduleAttachmentIdle(immediate: true)
                    #if DEBUG
                    self.faults?.commandDiagnostic?("secretDelivered")
                    #endif
                }
            }
            return answer.json
        }
        func crypto() throws -> String? {
            guard let answer = try cryptoJobs?.next() else { return nil }
            if answer.body { ioBodySource = .crypto }
            preferredIO = 0
            return answer.json
        }
        switch preferredIO {
        case 1: return try http() ?? secret() ?? crypto() ?? file() ?? ""
        case 2: return try secret() ?? crypto() ?? file() ?? http() ?? ""
        case 3: return try crypto() ?? file() ?? http() ?? secret() ?? ""
        default: return try file() ?? http() ?? secret() ?? crypto() ?? ""
        }
    }

    private func ioBody() throws -> String {
        try denyCleanupOwner()
        guard let source = ioBodySource else { throw HostFailure("I/O response body is unavailable") }
        ioBodySource = nil
        switch source {
        case .file:
            guard let jobs = attachmentJobs else { throw HostFailure("I/O response body is unavailable") }
            return jobs.body()
        case .http:
            guard let jobs = httpJobs else { throw HostFailure("I/O response body is unavailable") }
            let result = try jobs.body()
            if result.completed {
                // Defer logging until after this JSC turn; never invoke or pump
                // a host method recursively from a native ioBody callback.
                let generation = attachmentGeneration
                queue.async { [weak self] in
                    guard let self, self.attachmentGeneration == generation, self.started, !self.closed,
                          !self.invoking, !self.cleanupOwed, let context = self.context else { return }
                    _ = context.objectForKeyedSubscript("MindwtrHost")?.invokeMethod("nativeHTTPDelivered", withArguments: [])
                    context.exception = nil
                    self.scheduleAttachmentIdle(immediate: true)
                    #if DEBUG
                    self.faults?.commandDiagnostic?("httpDelivered")
                    #endif
                }
            }
            return result.base64
        case .crypto:
            guard let jobs = cryptoJobs else { throw HostFailure("I/O response body is unavailable") }
            let result = try jobs.body()
            if result.completed {
                let generation = attachmentGeneration
                queue.async { [weak self] in
                    guard let self, self.attachmentGeneration == generation, self.started, !self.closed,
                          !self.invoking, !self.cleanupOwed, let context = self.context else { return }
                    _ = context.objectForKeyedSubscript("MindwtrHost")?.invokeMethod("nativeCryptoDelivered", withArguments: [])
                    context.exception = nil
                    self.scheduleAttachmentIdle(immediate: true)
                    #if DEBUG
                    self.faults?.commandDiagnostic?("cryptoDelivered")
                    #endif
                }
            }
            return result.base64
        }
    }

    private func installBridge(_ context: JSContext) {
        let run: @convention(block) (String, String) -> String? = { [weak self] sql, parameters in
            guard let self else { return "!MindwtrNativeError:Native database unavailable" }
            return self.guarded { _ = try self.ordinaryGuardedSQL(sql, parameters: parameters); return nil }
        }
        let all: @convention(block) (String, String) -> String = { [weak self] sql, parameters in
            guard let self else { return "!MindwtrNativeError:Native database unavailable" }
            return self.guarded { try self.ordinaryGuardedSQL(sql, parameters: parameters) } ?? "[]"
        }
        let exec: @convention(block) (String) -> String? = { [weak self] sql in
            guard let self else { return "!MindwtrNativeError:Native database unavailable" }
            return self.guarded { _ = try self.ordinaryGuardedSQL(sql); return nil }
        }
        let logFile: @convention(block) (JSValue, JSValue) -> String = { [weak self] operation, text in
            guard let self, operation.isString, text.isString else { return "!MindwtrNativeError:Diagnostics file operation unavailable" }
            return self.guarded { try self.denyCleanupOwner(); return try self.diagnosticsFile.perform(operation.toString(), text: text.toString()) } ?? ""
        }
        let now: @convention(block) () -> Double = { ProcessInfo.processInfo.systemUptime * 1_000 }
        let random: @convention(block) (Int) -> String = { length in
            // Bundle evaluation needs entropy for in-memory identifiers before
            // cold cleanup settles. This bounded helper has no durable I/O authority.
            guard (0...65_536).contains(length) else { return "!MindwtrNativeError:Invalid random byte count" }
            if length == 0 { return "[]" }
            var bytes = [UInt8](repeating: 0, count: length)
            let result = bytes.withUnsafeMutableBytes { SecRandomCopyBytes(kSecRandomDefault, length, $0.baseAddress!) }
            guard result == errSecSuccess else { return "!MindwtrNativeError:Secure random failed" }
            return String(decoding: (try? JSONEncoder().encode(bytes)) ?? Data(), as: UTF8.self)
        }
        let rnState: @convention(block) (String) -> String? = { [weak self] change in
            guard let self, let legacy = self.legacyStorage else {
                return "!MindwtrNativeError:Legacy app storage is unavailable in the foundation"
            }
            return self.guarded {
                try self.denyCleanupOwner()
                try legacy.commit(changeJSON: change, checkpointURL: self.databaseURL.appendingPathExtension("rn-state.prewrite"))
                return nil
            }
        }
        let log: @convention(block) (String) -> Void = { [weak self] line in
            // Accept only the fixed, field-allowlisted release check. Generic JS
            // console output can contain task content and must not leave the host.
            guard let at = line.firstIndex(of: "{"),
                  let payload = try? NativeJSON.jsonObject(with: Data(line[at...].utf8)) as? [String: Any] else { return }
            if payload["scope"] as? String == "native-host",
               let encoded = payload["context"] as? String,
               let context = try? NativeJSON.jsonObject(with: Data(encoded.utf8)) as? [String: Any] {
                if context["releaseCheck"] as? String == "v1.3.3/native-readonly-completion" {
                    #if DEBUG
                    self?.faults?.commandDiagnostic?("readOnlyCompletion")
                    #endif
                    NSLog("Native completion refused for a read-only project releaseCheck=v1.3.3/native-readonly-completion")
                } else if context["releaseCheck"] as? String == "v1.3.3/native-token-replay",
                          context["outcome"] as? String == "matched" {
                    #if DEBUG
                    self?.faults?.commandDiagnostic?("tokenReplay")
                    #endif
                    NSLog("Native canonical token retry matched releaseCheck=v1.3.3/native-token-replay outcome=matched")
                } else if context["releaseCheck"] as? String == "v1.3.3/native-prepared-date-save",
                          let outcome = context["outcome"] as? String, ["applied", "replayed"].contains(outcome) {
                    #if DEBUG
                    self?.faults?.commandDiagnostic?("dateSave")
                    #endif
                    NSLog("Native prepared date save releaseCheck=v1.3.3/native-prepared-date-save outcome=%@", outcome)
                } else if context["releaseCheck"] as? String == "v1.3.3/native-prepared-recurrence-save",
                          let outcome = context["outcome"] as? String, ["applied", "replayed"].contains(outcome) {
                    #if DEBUG
                    self?.faults?.commandDiagnostic?("recurrenceSave:" + outcome)
                    #endif
                    NSLog("Native prepared recurrence save releaseCheck=v1.3.3/native-prepared-recurrence-save outcome=%@", outcome)
                } else if context["releaseCheck"] as? String == "v1.3.3/native-calendar-preference",
                          let outcome = context["outcome"] as? String, ["applied", "replayed"].contains(outcome) {
                    #if DEBUG
                    self?.faults?.commandDiagnostic?("calendarPreference:" + outcome)
                    #endif
                    NSLog("Native Calendar preference releaseCheck=v1.3.3/native-calendar-preference outcome=%@", outcome)
                } else if context["releaseCheck"] as? String == "v1.3.4/ios-reference-bulk-tag",
                          context["outcome"] as? String == "added",
                          Self.isInteger(context["count"]), let count = context["count"] as? NSNumber,
                          (1.0...10_000.0).contains(count.doubleValue) {
                    // Forward only the shared core's bounded aggregate receipt acknowledgment.
                    #if DEBUG
                    self?.faults?.commandDiagnostic?("referenceTasksAddTagCoreAck:" + String(count.intValue))
                    #endif
                    NSLog("Native Reference bulk tag confirmed releaseCheck=v1.3.4/ios-reference-bulk-tag count=%ld outcome=added", count.intValue)
                } else if context["releaseCheck"] as? String == "v1.3.4/ios-reference-bulk-remove-tag",
                          context["outcome"] as? String == "removed",
                          Self.isInteger(context["count"]), let count = context["count"] as? NSNumber,
                          (1.0...10_000.0).contains(count.doubleValue) {
                    // Forward only the shared core's bounded aggregate receipt acknowledgment.
                    #if DEBUG
                    self?.faults?.commandDiagnostic?("referenceTasksRemoveTagCoreAck:" + String(count.intValue))
                    #endif
                    NSLog("Native Reference bulk Remove tag confirmed releaseCheck=v1.3.4/ios-reference-bulk-remove-tag count=%ld outcome=removed", count.intValue)
                }
                return
            }
            // The shared host puts its fields in core's `context` (the part the Android log file keeps); older bundles used `extra`.
            guard payload["scope"] as? String == "native-ios",
                  let encodedExtra = (payload["context"] ?? payload["extra"]) as? String,
                  let extra = try? NativeJSON.jsonObject(with: Data(encodedExtra.utf8)) as? [String: Any] else { return }
            if extra["releaseCheck"] as? String == "v1.3.3/native-ios-legacy-json-import" {
                guard let outcome = extra["outcome"] as? String, ["imported", "abandoned", "none"].contains(outcome),
                      let rnState = extra["rnState"] as? String, ["updated", "unchanged", "failed"].contains(rnState) else { return }
                NSLog("Native iOS legacy JSON import releaseCheck=v1.3.3/native-ios-legacy-json-import outcome=%@ rnState=%@", outcome, rnState)
                return
            }
            guard extra["releaseCheck"] as? String == "v1.3.3/native-ios-dev-task-command",
                  let operation = extra["operation"] as? String, ["quickCapture", "complete", "areaFilter", "saveTaskDraft"].contains(operation),
                  let outcome = extra["outcome"] as? String, ["saved", "failed"].contains(outcome) else { return }
